comms.text:
@1 וַהֲוָה בְּיוֹמָא תְמִינָאָה קְרָא מֹשֶׁה לְאַהֲרֹן וְלִבְנוֹהִי וּלְסָבֵי יִשְׂרָאֵל:
@2 וַאֲמַר לְאַהֲרֹן סַב לָךְ עֵגֶל בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא שַׁלְמִין וְקָרֵב קֳדָם יְיָ:
@3 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵל לְמֵימָר סִבוּ צְפִיר בַּר עִזִין לְחַטָאתָא וְעֵגֶל וְאִמָר בְּנֵי שְׁנָא שַׁלְמִין לַעֲלָתָא:
@4 וְתוֹר וּדְכַר לְנִכְסַת קוּדְשַׁיָא לְדַבָּחָא קֳדָם יְיָ וּמִנְחָתָא דְפִילָא בִמְשָׁח אֲרֵי יוֹמָא דֵין יְקָרָא דַיְיָ מִתְגְלִי לְכוֹן:
@5 וּנְסִיבוּ יָת דִי פַקִיד מֹשֶׁה לָקֳדָם מַשְׁכַּן זִמְנָא וּקְרִיבוּ כָּל כְּנִישְׁתָּא וְקָמוּ קֳדָם יְיָ:
@6 וַאֲמַר מֹשֶׁה דֵין פִּתְגָמָא דִי פַקִיד יְיָ תַּעְבְּדוּן וְיִתְגְלִי לְכוֹן יְקָרָא דַיְיָ:
@7 וַאֲמַר מֹשֶׁה לְאַהֲרֹן קְרַב לְמַדְבְּחָא וְעִבֵד יָת חַטָאתָךְ וְיָת עֲלָתָךְ וְכַפֵּר עֲלָךְ וְעַל עַמָא וְעִבֵד יָת קֻרְבַּן עַמָא וְכַפֵּר עֲלֵיהוֹן כְּמָא דִי פַקִיד יְיָ:
@8 וּקְרַב אַהֲרֹן לְמַדְבְּחָא וּנְכֵס יָת עֶגְלָא דְחַטָאתָא דִי לֵהּ:
@9 וְקָרִיבוּ בְּנֵי אַהֲרֹן יָת דְמָא לֵהּ וּטְבַל אֶצְבְּעֵהּ בִּדְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא וְיָת דְמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא:
@10 וְיָת תַּרְבָּא וְיָת כָּלְיֵתָא וְיָת חִצְרָא מִן כַּבְדָא מִן חַטָאתָא אַסֵק לְמַדְבְּחָא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@11 וְיָת בִּשְׂרָא וְיָת מַשְׁכָא אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא:
@12 וּנְכֵס יָת עֲלָתָא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן לֵּהּ יָת דְמָא וּזְרָקֵהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@13 וְיָת עֲלָתָא אַמְטִיאוּ לֵהּ לְאֵבָרָהָא וְיָת רֵישָׁא וְאַסֵק עַל מַדְבְּחָא:
@14 וְחַלִיל יָת גַוָא וְיָת כְּרָעַיָא וְאַסֵק עַל עֲלָתָא לְמַדְבְּחָא:
@15 וְקָרֵב יָת קֻרְבַּן עַמָא וּנְסִב יָת צְפִירָא דְחַטָאתָא דִי לְעַמָא וְנָכְסֵהּ וְכַפֵּר בִּדְמֵהּ כְּקַדְמָאָה:
@16 וְקָרֵב יָת עֲלָתָא וְעָבְדַהּ כִּדְחָזֵי:
@17 וְקָרִיב יָת מִנְחָתָא וּמְלָא יְדֵהּ מִנַהּ וְאַסֵק עַל מַדְבְּחָא בַּר מֵעֲלַת צַפְרָא:
@18 וּנְכֵס יָת תּוֹרָא וְיָת דִכְרָא נִכְסַת קוּדְשַׁיָא דִי לְעַמָא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן יָת דְמָא לֵהּ וּזְרָקֵהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@19 וְיָת תַּרְבַּיָא מִן תּוֹרָא וּמִן דִכְרָא אֲלִיתָא וְחָפֵי גַוָא וְכָלְיֵתָא וַחֲצַר כַּבְדָא:
@20 וְשַׁוִיאוּ יָת תַּרְבַּיָא עַל חֶדְוָתָא וְאַסֵק תַּרְבַּיָא לְמַדְבְּחָא:
@21 וְיָת חֶדְוָתָא וְיָת שׁוֹקָא דְיַמִינָא אֲרֵים אַהֲרֹן אֲרָמָא קֳדָם יְיָ כְּמָא דִי פַקִיד מֹשֶׁה:
@22 וַאֲרֵם אַהֲרֹן יָת יְדוֹהִי עַל עַמָא וּבָרֵכִנוּן וּנְחַת מִלְמֶעְבַּד חַטָאתָא וַעֲלָתָא וְנִכְסַת קוּדְשַׁיָא:
@23 וְעַל מֹשֶׁה וְאַהֲרֹן לְמַשְׁכַּן זִמְנָא וּנְפָקוּ וּבָרִיכוּ יָת עַמָא וְאִתְגְלִי יְקָרָא דַיְיָ לְכָל עַמָא:
@24 וּנְפָקַת אֶשָׁתָא מִן קֳדָם יְיָ וַאֲכָלַת עַל מַדְבְּחָא יָת עֲלָתָא וְיָת תַּרְבַּיָא וַחֲזָא כָּל עַמָא וְשַׁבָּחוּ וּנְפָלוּ עַל אַפֵּיהוֹן:
@25 וּנְסִיבוּ בְנֵי אַהֲרֹן נָדָב וַאֲבִיהוּא גְבַר מַחְתִּיתֵהּ וִיהָבוּ בְהוֹן אֶשָׁתָא וְשַׁוִיאוּ עֲלַהּ קְטוֹרֶת וְקָרִיבוּ קֳדָם יְיָ אֶשָׁתָא נוּכְרֵיתָא דִי לָא פַקִיד יָתְהוֹן:
@26 וּנְפָקַת אֶשָׁתָא מִן קֳדָם יְיָ וַאֲכָלַת יָתְהוֹן וּמִיתוּ קֳדָם יְיָ:
@27 וַאֲמַר מֹשֶׁה לְאַהֲרֹן הוּא דִי מַלִיל יְיָ לְמֵימַר בְּקָרִיבַי אִתְקַדַשׁ וְעַל אַפֵּי כָל עַמָא אִתְיַקָר וּשְׁתִיק אַהֲרֹן:
@28 וּקְרָא מֹשֶׁה לְמִישָׁאֵל וּלְאֶלְצָפָן בְּנֵי עֻזִיאֵל אַח אֲבוּהִי דְאַהֲרֹן וַאֲמַר לְהוֹן קְרִיבוּ טוּלוּ יָת אֲחֵיכוֹן מִן קֳדָם אַפֵּי קוּדְשָׁא לְמִבָּרָא לְּמַשְׁרִיתָא:
@29 וּקְרִיבוּ וּנְטָלֻּנוּן בְּכִתֻּנֵיהוֹן לְמִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי מַלִיל מֹשֶׁה:
@30 וַאֲמַר מֹשֶׁה לְאַהֲרֹן וּלְאֶלְעָזָר וּלְאִיתָמָר בְּנוֹהִי רֵישֵׁיכוֹן לָא תְרַבּוּן פֵּרוּעַ וּלְבוּשֵׁיכוֹן לָא תְבַזְעוּן וְלָא תְמוּתוּן וְעַל כָּל כְּנִשְׁתָּא יְהֵא רוּגְזָא וַאֲחֵיכוֹן כָּל בֵּית יִשְׂרָאֵל יִבְכּוּן יָת יְקִדְתָּא דִי אוֹקִיד יְיָ:
@31 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְקוּן דִלְמָא תְמוּתוּן אֲרֵי מְשַׁח רְבוּתָא דַיְיָ עֲלֵיכוֹן וַעֲבָדוּ כְּפִתְגָמָא דְמֹשֶׁה:
@32 וּמַלִיל יְיָ עִם אַהֲרֹן לְמֵימָר:
@33 חֲמַר וּמְרַוֵי לָא תִשְׁתֵּי אַתְּ וּבְנָיךְ עִמָךְ בְּמֵעַלְכוֹן לְמַשְׁכַּן זִמְנָא וְלָא תְמוּתוּן קְיַם עָלָם לְדָרֵיכוֹן:
@34 וּלְאַפְרָשָׁא בֵּין קוּדְשָׁא וּבֵין חֻלָא וּבֵין מְסָאֲבָא וּבֵין דַכְיָא:
@35 וּלְאַלָפָא יָת בְּנֵי יִשְׂרָאֵל יָת כָּל קְיָמַיָא דִי מַלִיל יְיָ לְהוֹן בִּידָא דְמֹשֶׁה:
@36 וּמַלִיל מֹשֶׁה עִם אַהֲרֹן וְעִם אֶלְעָזָר וְעִם אִיתָמָר בְּנוֹהִי דְאִשְׁתָּאֲרוּ סִבוּ יָת מִנְחָתָא דְאִשְׁתָּאָרָת מִקֻרְבָּנַיָא דַיְיָ וְאִכְלוּהָ פַטִיר בִּסְטַר מַדְבְּחָא אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא:
@37 וְתֵיכְלוּן יָתַהּ בַּאֲתַר קַדִישׁ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ הִיא מִקֻרְבָּנַיָא דַיְיָ אֲרֵי כֵן אִתְפַּקָדִית:
@38 וְיָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא תֵּיכְלוּן בַּאֲתַר דְכֵי אַתְּ וּבְנָיךְ וּבְנָתָיךְ עִמָךְ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ אִתְיְהִיבוּ מִנִכְסַת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל:
@39 שׁוֹקָא דְאַפְרָשׁוּתָא וְחֶדְיָא דַאֲרָמוּתָא עַל קֻרְבָּנֵי תַרְבַּיָא יַיְתוּן לַאֲרָמָא אֲרָמָא קֳדָם יְיָ וִיהֵי לָךְ וְלִבְנָיךְ עִמָךְ לִקְיַם עָלָם כְּמָא דִי פַקִיד יְיָ:
@40 וְיָת צְפִירָא דְחַטָאתָא מִתְבַּע תָּבְעֵי מֹשֶׁה וְהָא אִתּוֹקָד וּרְגֵז עַל אֶלְעָזָר וְעַל אִיתָמָר בְּנֵי אַהֲרֹן דְאִשְׁתָּאֲרוּ לְמֵימָר:
@41 מָדֵין לָא אֲכַלְתּוּן יָת חַטָאתָא בַּאֲתַר קַדִישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא וְיָתַהּ יְהַב לְכוֹן לְסַלָחָא עַל חוֹבֵי כְנִשְׁתָּא לְכַפָּרָא עֲלֵיהוֹן קֳדָם יְיָ:
@42 הָא לָא אִתָּעַל יָת דְמַהּ לְבֵית קֻדְשָׁא גַוָאָה מֵיכַל תֵּכְלוּן יָתַהּ בְּקֻדְשָׁא כְּמָא דִי פַקֵדִית:
@43 וּמַלִיל אַהֲרֹן עִם מֹשֶׁה הָא יוֹמָא דֵין קְרִיבוּ יָת חַטָּאתְהוֹן וְיָת עֲלָתְהוֹן קֳדָם יְיָ וַעֲרָעָא יָתִי עָקָן כְּאִלֵין וְאִלוּפוֹן אֲכָלִית חַטָאתָא יוֹמָא דֵין הֲתַקֵן קֳדָם יְיָ:
@44 וּשְׁמַע מֹשֶׁה וּשְׁפַר בְּעֵינוֹהִי:
@45 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימַר לְהוֹן:
@46 מַלִילוּ עִם בְּנֵי יִשְׂרָאֵל לְמֵימַר דָא חַיְתָא דִי תֵיכְלוּן מִכָּל בְּעִירָא דִי עַל אַרְעָא:
@47 כֹּל דִי סְדִיקָן פַּרְסָתָא וּמַטִלְפָן טִלְפִין פַּרְסָתָא מַסְקָּא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:
@48 בְּרָם יָת דֵין לָא תֵיכְלוּן מִמַסְקֵי פִשְׁרָא וּמִמַסְדִיקֵי פַּרְסָתָא יָת גַמְלָא אֲרֵי מַסִיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:
@49 וְיָת טַפְזָא אֲרֵי מַסִיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:
@50 וְיָת אַרְנְבָא אֲרֵי מַסְקָא פִשְׁרָא הִיא וּפַרְסָתָא לָא סְדִיקָא מְסָאָבָא הִיא לְכוֹן:
@51 וְיָת חֲזִירָא אֲרֵי סְדִיק פַּרְסָתָא הוּא וּמַטִּלְפָן טִּלְפִין פַרְסָתֵהּ וְהוּא פִּשְׁרָא לָא פָשָׁר מְסָאָב הוּא לְכוֹן:
@52 מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבִלְתְּהוֹן לָא תִקְרְבוּן מְסָאֲבִין אִנוּן לְכוֹן:
@53 יָת דֵין תֵּיכְלוּן מִכֹּל דִי בְמַיָא כֹּל דִי לֵהּ צִיצִין וְקַלְפִין בְּמַיָא בְּיַמְמַיָא וּבְנַחֲלַיָא יַתְהוֹן תֵּיכְלוּן:
@54 וְכֹל דִי לֵית לֵהּ צִיצִין וְקַלְפִין בְּיַמְמַיָא וּבְנַחֲלַיָא מִכֹּל רִחֲשָׁא דְמַיָא וּמִכֹּל נַפְשָׁא חַיְתָא דִי בְמַיָא שִׁקְצָא אִנוּן לְכוֹן:
@55 וְשִׁקְצָא יְהוֹן לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וְיָת נְבִלְתְּהוֹן תְּשַׁקְצוּן:
@56 כֹּל דִי לֵית לֵהּ צִיצִין וְקַלְפִין בְּמַיָא שִׁקְצָא הוּא לְכוֹן:
@57 וְיָת אִלֵין תְּשַׁקְצוּן מִן עוֹפָא לָא יִתְאָכְלוּן שִׁקְצָא אִנוּן נִשְׁרָא וְעֲר וְעַזְיָא:
@58 וְדַיְתָא וְטָרָפִיתָא לִזְנַהּ:
@59 יָת כָּל עוּרְבָא לִזְנֵהּ:
@60 וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָא וְנָצָא לִזְנוֹהִי:
@61 וְקַרְיָא וְשָׁלֵינוּנָא וְקִפּוֹפָא:
@62 וּבַוְתָא וְקָתָא וִירַקְרֵקָא:
@63 וְחַוָרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַר טוּרָא וַעֲטַלֵפָא:
@64 כֹּל רִחֲשָׁא דְעוֹפָא דִמְהַלֵךְ עַל אַרְבַּע שִׁקְצָא הוּא לְכוֹן:
@65 בְּרַם יָת דֵין תֵּיכְלוּן מִכֹּל רִחֲשָׁא דְעוֹפָא דִמְהַלֵךְ עַל אַרְבַּע דִי לֵהּ קַרְצוּלִין מֵעִלַוֵי רַגְלוֹהִי לְקַפָּצָא בְהוֹן עַל אַרְעָא:
@66 יָת אִלֵין מִנְהוֹן תֵּיכְלוּן יָת גוֹבָא לִזְנֵהּ וְיָת רָשׁוּנָא לִזְנוֹהִי וְיָת חַרְגוֹלָא לִזְנוֹהִי וְיָת חַגָבָא לִזְנוֹהִי:
@67 וְכֹל רִחֲשָׁא דְעוֹפָא דִי לֵהּ אַרְבַּע רַגְלִין שִׁקְצָא הוּא לְכוֹן:
@68 וּלְאִלֵין תִּסְתָּאָבוּן כָּל דְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב עַד רַמשָׁא:
@69 וְכָל דְיִטוֹל:מִנְבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:
@70 לְכָל בְּעִירָא דִי הִיא סְדִיקָא פַרְסָתָא וְטִלְפִין לֵיתָהָא מַטִלְפָא וּפִשְׁרָא לֵיתָהָא מַסְקָא מְסָאֲבִין אִנוּן לְכוֹן כָּל דְיִקְרַב בְּהוֹן יְהֵי מְסָאָב:
@71 וְכֹל דִמְהַלֵךְ עַל יְדוֹהִי בְּכָל חַיְתָא דִמְהַלְכָא עַל אַרְבַּע מְסַאֲבִין אִנוּן לְכוֹן כָּל דְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵא מְסָאָב עַד רַמְשָׁא:
@72 וּדְיִטוֹל יָת נְבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא מְסַאֲבִין אִנוּן לְכוֹן:
@73 וְדֵין לְכוֹן מְסַאָבָא דְּרִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא חֻלְדָא וְעַכְבָּרָא וְצָבָא לִזְנוֹהִי:
@74 וְיָלָא וְכוֹחָא וְחֻלְטֵיתָא וְחֻמְטָא וְאָשׁוּתָא:
@75 אִלֵין דִמְסַאֲבִין לְכוֹן בְּכָל רִחֲשָׁא כֹּל דְיִקְרַב בְּהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:
@76 וְכָל דִי יִפֵּל עֲלוֹהִי מִנְהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב מִכָּל מָאן דְעָא אוֹ לְבוּשׁ אוֹ מְשַׁךְ אוֹ שָׂק כָּל מָאן דִי תִתְעֲבֵד עִבִידָא בְּהוֹן בְּמַיָא יִתָּעַל וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@77 וְכָל מָאן דַחֲסַף דִי יִפֵּל מִנְהוֹן לְגַוֵהּ כֹּל דִי בְגַוֵהּ יִסְתָּאַב וְיָתֵהּ תְּתַבְּרוּן:
@78 מִכָּל מֵיכְלָא דְמִתְאֲכֵל דִי יַעֲלוּן עֲלוֹהִי מַיָא יְהֵי מְסָאָב וְכָל מַשְׁקֵה דִי יִשְׁתֵּתֵי בְּכָל מָאן יְהֵי מְסָאָב:
@79 וְכֹל דִי יִפֹּל מִנְבִלְתְּהוֹן עֲלוֹהִי יְהֵי מְסָאָב תַּנוּר וְכִירַיִם יִתָּרְעוּן מְסַאֲבִין אִנוּן וּמְסַאֲבִין יְהוֹן לְכוֹן:
@80 בְּרַם מַעְיָן וְגוֹב בֵּית כְּנִישׁוּת מַיָא יְהֵי דְכֵי וּדְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב:
@81 וַאֲרֵי יִפֵּל מִנְבִלְתְּהוֹן עַל כָּל בַּר זְרַע זֵרוּעַ דִי יִזְדְרָע דְכֵי הוּא:
@82 וַאֲרֵי יִתְיַהֲבוּן מַיָא עַל בַּר זַרְעָא וְיִפֵּל מִנְבִלְתְּהוֹן עֲלוֹהִי מְסָאָב הוּא לְכוֹן:
@83 וַאֲרֵי יְמוּת מִן בְּעִירָא דִי הִיא לְכוֹן לְמֵיכָל דְיִקְרַב בִּנְבִלְתַּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@84 וּדְיֵכוּל מִנְבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטוֹל יָת נְבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:
@85 וְכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא שִׁקְצָא הוּא לָא יִתְאָכֵל:
@86 כֹּל דִמְהַלֵךְ עַל מְעוֹהִי וְכֹל דִמְהַלֵךְ עַל אַרְבַּע עַד כָּל סְגִיאוּת רַגְלָאִין לְכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא לָא תֵיכְלֻנוּן אֲרֵי שִׁקְצָא אִנוּן:
@87 לָא תְשַׁקְצוּ יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְרָחֵשׁ וְלָא תִסְתַּאֲבוּן בְּהוֹן וְתִסְתַּאֲבוּן פּוֹן בְּהוֹן:
@88 אֲרֵי אֲנָא יְיָ אֶלָהָכוֹן וְתִתְקַדְשׁוּן וּתְהוֹן קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא וְלָא תְסַאֲבוּן יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא:
@89 אֲרֵי אֲנָא יְיָ דְאַסֵק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ וּתְהוֹן קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא:
@90 דָא אוֹרַיְתָא דִבְעִירָא וּדְעוֹפָא וּדְכָל נַפְשָׁתָא חַיְתָא דִרְחֵשָׁא בְּמַיָא וּלְכָל נַפְשָׁא דִרְחֵשָׁא עַל אַרְעָא:
@91 לְאַפְרָשָׁא בֵּין מְסָאָבָא וּבֵין דַכְיָא וּבֵין חַיְתָא דְמִתְאַכְלָא וּבֵין חַיְתָא דִי לָא מִתְאַכְלָא: פפפ:

@1 **ויהי ביום השמיני.** שמיני למלואים, הוא ראש חדש ניסן, שהוקם המשכן בו ביום ונטל עשר עטרות השנויות בסדר עולם (פרק ז) : **ולזקני ישראל.** להשמיעם שעל פי הדבור אהרן נכנס ומשמש בכהנה גדולה, ולא יאמרו מאליו נכנס:
@2 **קח לך עגל.** להודיע שמכפר לו הקדוש ברוך הוא על ידי עגל זה על מעשה העגל שעשה:
@4 **כי היום ה' נראה אליכם.** להשרות שכינתו במעשה ידיכם לכך קרבנות הללו באין חובה ליום זה:
@7 **קרב אל המזבח.** שהיה אהרן בוש וירא לגשת. אמר לו משה למה אתה בוש, לכך נבחרת: **את חטאתך.** עגל בן בקר: **ואת עלתך.** איל: **קרבן העם.** שעיר עזים ועגל וכבש. כל מקום שנאמר עגל, בן שנה הוא, ומכאן אתה למד:
@11 **ואת הבשר ואת העור** וגו' **.** לא מצינו חטאת חיצונה נשרפת אלא זו ושל מלאים, וכלן על פי הדבור:
@12 **וימצאו.** לשון הושטה והזמנה:
@15 **ויחטאהו.** עשהו כמשפט חטאת: **כראשון.** כעגל שלו:
@16 **ויעשה כמשפט.** המפורש בעולת נדבה בויקרא (פרק א) :
@17 **וימלא כפו.** היא קמיצה: **מלבד עלת הבקר.** כל אלה עשה אחר עולת התמיד:
@19 **והמכסה.** חלב המכסה את הקרב:
@20 **וישימו את החלבים על החזות.** לאחר התנופה נתנן כהן המניף לכהן אחר להקטירם, נמצאו העליונים למטה:
@22 **ויברכם.** ברכת כהנים יברכך, יאר, ישא: **וירד.** מעל המזבח:
@23 **ויבא משה ואהרן** וגו' **.** למה נכנסו, מצאתי בפרשת מלאים בבריתא הנוספת על תורת כהנים שלנו למה נכנס משה עם אהרן, ללמדו על מעשה הקטרת. או לא נכנס אלא לדבר אחר, הריני דן ירידה וביאה טעונות ברכה, מה ירידה מעין עבודה, אף ביאה מעין עבודה, הא למדת למה נכנס משה עם אהרן, ללמדו על מעשה הקטרת. דבר אחר כיון שראה אהרן שקרבו כל הקרבנות ונעשו כל המעשים ולא ירדה שכינה לישראל, היה מצטער ואמר יודע אני שכעס הקדוש ברוך הוא עלי ובשבילי לא ירדה שכינה לישראל. אמר לו למשה, משה אחי כך עשית לי, שנכנסתי ונתבישתי. מיד נכנס משה עמו ובקשו רחמים וירדה שכינה לישראל: **ויצאו ויברכו את העם.** אמרו ויהי נועם ה' אלהינו עלינו (תהלים צ יז) , יהי רצון שתשרה שכינה במעשה ידיכם. לפי שכל שבעת ימי המלואים, שהעמידו משה למשכן ושמש בו ופרקו בכל יום, לא שרתה בו שכינה, והיו ישראל נכלמים ואומרים למשה, משה רבנו, כל הטורח שטרחנו, שתשרה שכינה בינינו ונדע שנתכפר לנו עון העגל. לכך אמר להם זה הדבר אשר צוה ה' תעשו וירא אליכם כבוד ה' (פסוק ו) , אהרן אחי כדאי וחשוב ממני שעל ידי קרבנותיו ועבודתו תשרה שכינה בכם ותדעו שהמקום בחר בו:
@24 **וירנו.** כתרגומו:
@26 **ותצא אש.** רבי אלעזר אומר לא מתו בני אהרן אלא על ידי שהורו הלכה בפני משה רבן. רבי ישמעאל אומר שתויי יין נכנסו למקדש, תדע שאחר מיתתן הזהיר הנותרים שלא יכנסו שתויי יין למקדש. משל למלך, שהיה לו בן בית וכו' , כדאיתא בויקרא רבה:
@27 **הוא אשר דבר** וגו' **.** היכן דבר ונועדתי שמה לבני ישראל ונקדש בכבודי (שמות כט מג) . אל תקרי בכבודי אלא במכבדי. אמר לו משה לאהרן, אהרן אחי יודע הייתי שיתקדש הבית במידעיו של מקום והייתי סבור או בי או בך, עכשיו רואה אני שהם גדולים ממני וממך: **וידם אהרן.** קבל שכר על שתיקתו. ומה שכר קבל, שנתיחד עמו הדבור, שנאמרה לו לבדו פרשת שתויי יין: **בקרבי.** בבחירי: **ועל פני כל העם אכבד.** כשהקדוש ברוך הוא עושה דין בצדיקים מתירא ומתעלה ומתקלס, אם כן באלו, כל שכן ברשעים, וכן הוא אומר (תהלים סח לו) נורא אלהים ממקדשיך, אל תקרא ממקדשיך אלא ממקדשיך:
@28 **דד אהרן.** עזיאל אחי עמרם היה, שנאמר (שמות ו יח) ובני קהת וגו' : **שאו את אחיכם** וגו' **.** כאדם האומר לחברו העבר את המת מלפני הכלה, שלא לערבב את השמחה:
@29 **בכתנתם.** של מתים. מלמד שלא נשרפו בגדיהם אלא נשמתם, כמין שני חוטין של אש נכנסו לתוך חטמיהם:
@30 **אל תפרעו.** אל תגדלו שער. מכאן שאבל אסור בתספורת, אבל אתם אל תערבבו שמחתו של מקום: **ולא תמתו.** הא אם תעשו כן תמותו: **ואחיכם כל בית ישראל.** מכאן שצרתן של תלמידי חכמים מטלת על הכל להתאבל בה:
@33 **יין ושכר.** יין דרך שכרותו: **בבאכם אל אהל מועד.** אין לי אלא בבואם להיכל, בגשתם למזבח מנין, נאמר כאן ביאת אהל מועד, ונאמר בקדוש ידים ורגלים ביאת אהל מועד, מה להלן עשה גישת מזבח כביאת אהל מועד, אף כאן עשה גישת מזבח כביאת אהל מועד:
@34 **ולהבדיל.** כדי שתבדילו בין עבודה קדושה למחללת, הא למדת שאם עבד, עבודתו פסולה:
@35 **ולהורת.** למד שאסור שכור בהוראה. יכול יהא חיב מיתה, תלמוד לומר אתה ובניך אתך ולא תמותו (פסוק ט) , כהנים בעבודתם במיתה, ואין חכמים בהוראתם במיתה:
@36 **הנותרים.** מן המיתה. מלמד שאף עליהם נקנסה מיתה על עון העגל, הוא שנאמר (דברים ט כ) ובאהרן התאנף ה' מאד להשמידו, ואין השמדה אלא כלוי בנים, שנאמר (עמוס ב ט) ואשמיד פריו ממעל, ותפלתו של משה בטלה מחצה, שנאמר (דברים ט כ) ואתפלל גם בעד אהרן בעת ההיא: **קחו את המנחה.** אף על פי שאתם אוננין וקדשים אסורים לאונן: **את המנחה.** זו מנחת שמיני ומנחת נחשון: **ואכלוה מצות.** מה תלמוד לומר, לפי שהיא מנחת צבור ומנחת שעה ואין כיוצא בה לדורות, הצרך לפרש בה דין שאר מנחות:
@37 **וחק בניך.** אין לבנות חק בקדשים: **כי כן צויתי.** באנינות יאכלוה:
@38 **ואת חזה התנופה.** של שלמי צבור: **תאכלו במקום טהור.** וכי את הראשונים אכלו במקום טמא, אלא הראשונים שהם קדשי קדשים הזקקה אכילתם במקום קדוש, אבל אלו אין צריכים תוך הקלעים, אבל צריכים הם להאכל תוך מחנה ישראל, שהוא טהור מלכנס שם מצורעים. מכאן שקדשים קלים נאכלין בכל העיר: **אתה ובניך ובנתיך.** אתה ובניך בחלק, אבל בנותיך לא בחלק, אלא אם תתנו להן מתנות, רשאות הן לאכול בחזה ושוק. או אינו אלא אף הבנות בחלק, תלמוד לומר כי חקך וחק בניך נתנו, חק לבנים ואין חק לבנות:
@39 **שוק התרומה וחזה התנופה.** לשון אשר הונף ואשר הורם. תנופה מוליך ומביא, תרומה מעלה ומוריד. ולמה חלקן הכתוב, תרומה בשוק ותנופה בחזה, לא ידענו, ששניהם בהרמה והנפה: **על אשי החלבים.** מכאן שהחלבים למטה בשעת תנופה, וישוב המקראות שלא יכחישו זה את זה, כבר פרשתי שלשתן בצו את אהרן (ז ל) :
@40 **שעיר החטאת.** שעיר מוספי ראש חדש. ושלשה שעירי חטאות קרבו בו ביום שעיר עזים, ושעיר נחשון ושעיר ראש חדש, ומכלן לא נשרף אלא זה. ונחלקו בדבר חכמי ישראל יש אומרים, מפני הטמאה שנגעה בו נשרף. ויש אומרים, מפני אנינות נשרף, לפי שהוא קדשי דורות, אבל בקדשי שעה סמכו על משה שאמר להם במנחה (פסוק יב) ואכלוה מצות: **דרש דרש.** שתי דרישות הללו מפני מה נשרף זה, ומפני מה נאכלו אלו, כך הוא בתורת כהנים: **על אלעזר ועל איתמר.** בשביל כבודו של אהרן הפך פניו כנגד הבנים וכעס: **לאמר.** אמר להם, השיבוני על דברי:
@41 **מדוע לא אכלתם את החטאת במקום הקדש.** וכי חוץ לקדש אכלוה, והלא שרפוה, ומה הוא אומר במקום הקדש, אלא אמר להם שמא חוץ לקלעים יצאה ונפסלה: **כי קדש קדשים הוא.** ונפסלת ביוצא, והם אמרו לו לאו. אמר להם הואיל ובמקום הקדש היתה, מדוע לא אכלתם אותה: **ואתה נתן לכם לשאת** וגו' **.** שהכהנים אוכלים ובעלים מתכפרים: **לשאת את עון העדה.** מכאן למדנו ששעיר ראש חדש היה, שהוא מכפר על עון טמאת מקדש וקדשיו, שחטאת שמיני וחטאת נחשון לא לכפרה באו:
@42 **הן לא הובא** וגו' **.** שאלו הובא היה לכם לשרפה, כמו שנאמר (ויקרא ו כג) וכל חטאת אשר יובא מדמה וגו' : **אכל תאכלו אתה.** היה לכם לאכלה אף על פי שאתם אוננים: **כאשר צויתי.** לכם במנחה:
@43 **וידבר אהרן.** אין לשון דבור אלא לשון עז, שנאמר (במדבר כא ה) וידבר העם וגו' . אפשר משה קצף על אלעזר ועל איתמר, ואהרן מדבר, הא ידעת שלא היתה אלא מדרך כבוד. אמרו אינו בדין שיהא אבינו יושב ואנו מדברים לפניו, ואינו בדין שיהא תלמיד משיב את רבו. יכול מפני שלא היה באלעזר להשיב, תלמוד לומר (במדבר לא כא) ויאמר אלעזר הכהן אל אנשי הצבא וגו' , הרי כשרצה, דבר לפני משה ולפני הנשיאים, זו מצאתי בספרי של פנים שני: **הן היום הקריבו.** מהו אומר, אלא אמר להם משה שמא זרקתם דמה אוננים, שהאונן שעבד חלל. אמר לו אהרן וכי הם הקריבו, שהם הדיוטות, אני הקרבתי, שאני כהן גדול ומקריב אונן: **ותקראנה אתי כאלה.** אפלו לא היו המתים בני אלא שאר קרובים שאני חיב להיות אונן עליהם כאלו, כגון כל האמורים בפרשת כהנים שהכהן מטמא להם: **ואכלתי חטאת.** ואם אכלתי הייטב וגו' : **היום.** אבל אנינות לילה מתר, שאין אונן אלא יום קבורה: **הייטב בעיני ה'.** אם שמעת בקדשי שעה אין לך להקל בקדשי דורות:
@44 **וייטב בעיניו.** הודה ולא בוש לומר לא שמעתי:
@45 **אל משה ואל אהרן.** למשה אמר שיאמר לאהרן: **לאמר אליהם.** אמר שיאמר לאלעזר ולאיתמר, או אינו אלא לאמר לישראל, כשהוא אומר דברו אל בני ישראל, הרי דבור אמור לישראל, הא מה אני מקים לאמר אליהם, לבניו לאלעזר ולאיתמר:
@46 **דברו אל בני ישראל.** את כלם השוה להיות שלוחים בדבר זה, לפי שהשוו בדמימה וקבלו עליהם גזרת המקום באהבה: **זאת החיה.** לשון חיים, לפי שישראל דבוקים במקום וראויין להיות חיים, לפיכך הבדילם מן הטמאה וגזר עליהם מצות, ולאמות העולם לא אסר כלום. משל לרופא שנכנס לבקר את החולה וכו' , כדאיתא במדרש רבי תנחומא: **זאת החיה.** מלמד שהיה משה אוחז בחיה ומראה אותה לישראל, זאת תאכלו וזאת לא תאכלו: **את זה תאכלו** וגו' **.** אף בשרצי המים אחז מכל מין ומין והראה להם. וכן בעוף ואת אלה תשקצו מן העוף. וכן בשרצים וזה לכם הטמא: **זאת החיה מכל הבהמה.** מלמד שהבהמה בכלל חיה:
@47 **מפרסת.** כתרגומו סדיקא: **פרסה.** פלאנט''ה בלע''ז [כף רגל] : **ושסעת שסע.** שמבדלת מלמעלה ומלמטה בשתי צפרנין, כתרגומו ומטלפא טלפין, שיש שפרסותיו סדוקות מלמעלה ואינן שסועות ומבדלות לגמרי, שמלמטה מחברות: **מעלת גרה.** מעלה ומקיאה האוכל ממעיה ומחזרת אותו לתוך פיה לכתשו ולטחנו הדק: **גרה.** כך שמו. ויתכן להיות מגזרת מים הנגרים (שמואל ב יד יד) , שהוא נגרר אחר הפה. ותרגומו פשרא שעל ידי הגרה האוכל נפשר ונמוח: **בבהמה.** תיבה זו יתרה היא לדרשה, להתיר את השליל הנמצא במעי אמו: **אתה תאכלו.** ולא בהמה טמאה. והלא באזהרה היא, אלא לעבור עליה בעשה ולא תעשה:
@52 **מבשרם לא תאכלו.** אין לי אלא אלו, שאר בהמה טמאה שאין לה שום סימן טהרה מנין, אמרת קל וחמר ומה אלו שיש בהן קצת סימני טהרה אסורות וכו' : **מבשרם.** על בשרם באזהרה, ולא על עצמות וגידין וקרנים וטלפים: **ובנבלתם לא תגעו.** יכול יהו ישראל מזהרים על מגע נבלה, תלמוד לומר אמור אל הכהנים וגו' (ויקרא כא א) , כהנים מזהרין ואין ישראל מזהרין. קל וחמר מעתה ומה טמאת מת חמורה, לא הזהיר בה אלא כהנים, טמאת נבלה קלה לא כל שכן. ומה תלמוד לומר לא תגעו, ברגל. זהו שאמרו חיב אדם לטהר עצמו ברגל:
@53 **סנפיר.** אלו ששט בהם: **קשקשת.** אלו קלפים הקבועים בו, כמו שנאמר (שמואל א יז ה) ושריון קשקשים הוא לבוש:
@54 **שרץ.** בכל מקום משמעו דבר נמוך שרוחש ונע ונד על הארץ:
@55 **ושקץ יהיו.** לאסר את עירוביהן, אם יש בו בנותן טעם: **מבשרם.** אינו מזהר על הסנפירים ועל העצמות: **ואת נבלתם תשקצו.** לרבות יבחושין שסננן. יבחושין מושקירונ''ש בלע''ז :
@56 **כל אשר אין לו** וגו' **.** מה תלמוד לומר, שיכול אין לי שיהא מתר אלא המעלה סימנין שלו ליבשה, השירן במים מנין, תלמוד לומר כל אשר אין לו סנפיר וקשקשת במים, הא אם היו לו במים אף על פי שהשירן בעליתו מתר:
@57 **לא יאכלו.** לחיב את המאכילן לקטנים. שכך משמעו לא יהיו נאכלים על ידך. או אינו אלא לאסרו בהנאה, תלמוד לומר (דברים יד יב) לא תאכלו, באכילה אסורין בהנאה מתרין. כל עוף שנאמר בו למינה, למינו, למינהו, יש באותו המין שאין דומין זה לזה, לא במראיהם ולא בשמותם, וכלן מין אחד:
@60 **הנץ.** אישפרויי''ר :
@61 **השלך.** פרשו רבותינו זה השולה דגים מן הים. וזהו שתרגם אנקלוס ושלינונא: **כוס וינשוף.** הם צואיטי''ש הצועקים בלילה ויש להם לסתות כאדם. ועוד אחר דומה לו שקורין יב''ן [לילית] :
@62 **התנשמת.** היא קלב''א שורי''ץ [עטלף] ודומה לעכבר ופורחת בלילה. ותנשמת האמורה בשרצים היא דומה לה, ואין לה עינים וקורין לה טלפ''א [חפרפרת] :
@63 **החסידה.** זו דיה לבנה ציגוני''ה . ולמה נקרא שמה חסידה, שעושה חסידות עם חברותיה במזונות: **האנפה.** היא דיה רגזנית. ונראה לי שזו היא שקורין לה היירו''ן : **הדוכיפת.** תרנגול הבר וכרבלתו כפולה ובלע''ז הירופ''א , ולמה נקרא שמו דוכיפת, שהודו כפות, וזו היא כרבלתו. תרגום אנקלוס ונגר טורא נקרא על שם מעשיו, כמו שפרשו רבותינו במסכת גטין בפרק מי שאחזו (דף סח ב) :
@64 **שרץ העוף.** הם הדקים הנמוכים הרוחשין על הארץ, כגון זבובים וצרעין ויתושין וחגבים:
@65 **על ארבע.** על ארבע רגלים: **ממעל לרגליו.** סמוך לצוארו יש לו כמין שתי רגלים לבד ארבע רגליו, וכשרוצה לעוף ולקפוץ מן הארץ מתחזק באותן שתי כרעים ופורח, ויש הרבה מהם במקומנו בינותינו, כאותן שקורין לנגושט''א , אבל אין אנו בקיאין בהן, שארבעה סימני טהרה נאמרו בהם ארבע רגלים, וארבע כנפים, וקרסלין אלו כרעים הכתובים כאן, וכנפיו חופין את רבו. וכל סימנים הללו מצויין באותן שבינותינו, אבל יש שראשן ארוך ויש שאין להם זנב וצריך שיהא שמו חגב, ובזה אין אנו יודעים להבדיל ביניהם:
@67 **וכל שרץ העוף** וגו' **.** בא ללמד שאם יש לו חמש טהור:
@68 **ולאלה.** העתידין להאמר למטה בענין: **תטמאו.** כלומר בנגיעתם יש טמאה:
@69 **וכל הנשא מנבלתם.** כל מקום שנאמרה טמאת משא, חמורה מטמאת מגע, שהיא טעונה כבוס בגדים:
@70 **מפרסת פרסה ושסע איננה שסעת.** כגון גמל שפרסתו סדוקה למעלה, אבל למטה היא מחברת. כאן למדך שנבלת בהמה טמאה מטמאה, ובענין שבסוף הפרשה פרש על בהמה טהורה:
@71 **על כפיו.** כגון כלב ודב וחתול: **טמאים הם לכם.** למגע:
@73 **וזה לכם הטמא.** כל טמאות הללו אינן לאסור אכילה אלא לטמאה ממש, להיות טמא במגען ונאסר לאכול תרומה וקדשים ולכנס במקדש: **החלד.** מושטיל''ה [נמיה] : **והצב.** פרוי''ט [קרפדה] שדומה לצפרדע:
@74 **והאנקה.** היריצו''ן [קפוד] : **והלטאה.** לישרד ''ה: **והחמט.** לימצ''ה [חלזון] : **והתנשמת.** טלפ''א [חפרפרת] :
@76 **במים יובא.** ואף לאחר טבילתו טמא הוא לתרומה עד הערב, ואחר כך וטהר בהערב השמש:
@77 **אל תוכו.** אין כלי חרס מטמא אלא מאוירו: **כל אשר בתוכו יטמא.** הכלי חוזר ומטמא מה שבאוירו: **ואתו תשברו.** למד שאין לו טהרה במקוה:
@78 **מכל האכל אשר יאכל.** מוסב על מקרא העליון, כל אשר בתוכו יטמא, מכל האכל אשר יאכל אשר יבא עליו מים והוא בתוך כלי חרס הטמא, יטמא. וכן כל משקה אשר ישתה בכל כלי, והוא בתוך כלי חרס הטמא, יטמא. למדנו מכאן דברים הרבה. למדנו שאין אוכל מכשר ומתקן לקבל טמאה עד שיבאו עליו מים פעם אחת, ומשבאו עליו מים פעם אחת מקבל טמאה לעולם ואפלו נגוב. והיין והשמן וכל הנקרא משקה מכשיר זרעים לטמאה כמים. שכך יש לדרוש המקרא, אשר יבא עליו מים או כל משקה אשר ישתה בכל כלי יטמא האוכל. ועוד למדו רבותינו מכאן, שאין ולד הטמאה מטמא כלים, שכך שנינו יכול יהיו כל הכלים מטמאין מאויר כלי חרס, תלמוד לומר כל אשר בתוכו יטמא מכל האוכל, אוכל מטמא מאויר כלי חרס, ואין כל הכלים מטמאין מאויר כלי חרס, לפי שהשרץ אב הטמאה והכלי, שנטמא ממנו, ולד הטמאה, לפיכך אינו חוזר ומטמא כלים שבתוכו. ולמדנו עוד, שהשרץ שנפל לאויר תנור והפת בתוכו, ולא נגע השרץ בפת, התנור ראשון והפת שניה. ולא נאמר רואין את התנור כאלו מלא טמאה ותהא הפת תחלה, שאם אתה אומר כן לא נתמעטו כל הכלים מלהטמא מאויר כלי חרס, שהרי טמאה עצמה נגעה בהן מגבן. ולמדנו עוד על ביאת מים, שאינה מכשרת זרעים אלא אם כן נפלו עליהן משנתלשו, שאם אתה אומר מקבלין הכשר במחבר, אין לך שלא באו עליו מים, ומהו אומר אשר יבוא עליו מים, משנתלשו. ולמדנו עוד שאין אוכל מטמא אחרים אלא אם כן יש בו כביצה, שנאמר אשר יאכל, אוכל הנאכל בבת אחת, ושערו חכמים אין בית הבליעה מחזיק יותר מביצת תרנגולת:
@79 **תנור וכירים.** כלים המטלטלין הם, והם של חרס ויש להן תוך, ושופת את הקדרה על נקב החלל ושניהם פיהם למעלה: **יתץ.** שאין לכלי חרס טהרה בטבילה: **וטמאים יהיו לכם.** שלא תאמר מצוה אני לנתצם, תלמוד לומר וטמאים יהיו לכם, אם רצה לקימן בטמאתן רשאי:
@80 **אך מעין ובור מקוה מים.** המחברים לקרקע, אין מקבלין טמאה. ועוד יש לך ללמוד יהיה טהור הטובל בהם מטמאתו: **ונגע בנבלתם יטמא.** אפלו הוא בתוך מעין ובור ונוגע בנבלתם יטמא, שלא תאמר קל וחומר אם מטהר את הטמאים מטמאתם, קל וחמר שיציל את הטהור מלטמא, לכך נאמר ונוגע בנבלתם יטמא:
@81 **זרע זרוע.** זריעה של מיני זרעונין. זרוע שם דבר הוא, כמו ויתנו לנו מן הזרועים: (דניאל א יב) **טהור הוא.** למדך הכתוב שלא הכשר ונתקן לקרות אוכל לקבל טמאה, עד שיבואו עליו מים:
@82 **וכי יתן מים על זרע.** לאחר שנתלש, שאם תאמר יש הכשר במחבר, אין לך זרע שלא הכשר: **מים על זרע.** בין מים בין שאר משקין, בין נפלו הם על הזרע, בין הזרע נפל לתוכן, הכל נדרש בתורת כהנים: **ונפל מנבלתם עליו.** אף משנגב מן המים, שלא הקפידה תורה אלא להיות עליו שם אוכל, ומשירד עליו הכשר קבלת טמאה פעם אחת, שוב אינו נעקר המנו:
@83 **בנבלתה.** ולא בעצמות וגידים ולא בקרנים וטלפים ולא בעור:
@84 **והנשא את נבלתה.** חמורה טמאת משא מטמאת מגע, שהנושא מטמא בגדים, והנוגע אין בגדיו טמאין, שלא נאמר בו יכבס בגדיו: **והאכל מנבלתה.** יכול תטמאנו אכילתו, כשהוא אומר בנבלת עוף טהור (ויקרא כב ח) נבלה וטרפה לא יאכל לטמאה בה, אותה מטמאה בגדים באכילתה, ואין נבלת בהמה מטמאה בגדים באכילתה בלא משא, כגון אם תחבה לו חברו בבית הבליעה, אם כן מה תלמוד לומר האכל, לתן שעור לנושא ולנוגע כדי אכילה והוא כזית: **וטמא עד הערב.** אף על פי שטבל צריך הערב שמש:
@85 **השרץ על הארץ.** להוציא את היתושין שבכליסין ושבפולין ואת הזיזין שבעדשים, שהרי לא שרצו על הארץ אלא בתוך האוכל, אבל משיצאו לאויר ושרצו הרי נאסרו: **לא יאכל.** לחיב על המאכיל כאוכל. ואין קרוי שרץ אלא דבר נמוך קצר רגלים, שאינו נראה אלא כרוחש ונד:
@86 **הולך על גחון.** זה נחש, ולשון גחון שחיה, שהולך שח ונופל על מעיו: **כל הולך.** להביא השלשולין ואת הדומה לדומה: **הולך על ארבע.** זה עקרב: **כל.** להביא את החפושית אישקרבו''ט בלע''ז ואת הדומה לדומה: **מרבה רגלים.** זה נדל, שרץ שיש לו רגלים מראשו ועד זנבו לכאן ולכאן, וקורין ציינפיי''ש :
@87 **אל תשקצו.** באכילתן, שהרי כתיב נפשותיכם, ואין שקוץ נפש במגע, וכן ולא תטמאו באכילתן: **ונטמתם בם.** אם אתם מטמאין בהם בארץ אף אני מטמא אתכם בעולם הבא ובישיבת מעלה:
@88 **כי אני ה' אלהיכם.** כשם שאני קדוש שאני ה' אלהיכם, כך והתקדשתם קדשו עצמכם למטה: **והייתם קדשים.** לפי שאני אקדש אתכם למעלה ובעולם הבא: **ולא תטמאו** וגו' **.** לעבור עליהם בלאוין הרבה. וכל לאו מלקות, וזהו שאמרו בתלמוד [ מכות טז ] אכל פוטיתא לוקה ארבע, נמלה לוקה חמש, צרעה לוקה שש:
@89 **כי אני ה' המעלה אתכם.** על מנת שתקבלו מצותי העלתי אתכם. דבר אחר כי אני ה' המעלה אתכם, בכלן כתיב והוצאתי, וכאן כתיב המעלה, תנא דבי רבי ישמעאל אלמלי לא העלתי את ישראל ממצרים אלא בשביל שאין מטמאין בשרצים כשאר אמות, דים, ומעליותא היא גבייהו, זהו לשון מעלה:
@91 **להבדיל.** לא בלבד השונה, אלא שתהא יודע ומכיר ובקי בהן: **בין הטמא ובין הטהר.** צריך לומר בין חמור לפרה והלא כבר מפורשים הם, אלא בין טמאה לך לטהורה לך, בין נשחט חציו של קנה לנשחט רבו: **ובין החיה הנאכלת.** צריך לומר בין צבי לערוד, והלא כבר מפורשים הם, אלא בין שנלדו בה סימני טרפה כשרה, לנלדו בה סימני טרפה פסולה:

@1 **ויהי ביום השמיני**. צריך לדעת מה טעם אמר ויהי ובמסכת מגילה (דף י) אמר רבי לוי דבר זה מסורת בידינו מאנשי כנסת הגדולה כל מקום שנאמר ויהי אינו אלא לשון צער, ומקשה והכתיב ויהי ביום השמיני ותניא אותו היום היתה שמחה לפני הקב''ה כיום בריאת שמים וארץ כתיב הכא ויהי וגו' וכתיב התם (בראשית א ה) ויהי ערב ויהי בקר וגו', ומתרץ הא מתו נדב ואביהוא, ומקשה עוד ויהי בשמונים שנה (מ''א ו) ויהי כאשר ראה יעקב (ויצא כט י) וגו' ויהי ערב ויהי בקר וגו', ומתרץ רב אשי כל ויהי איכא הכי ואיכא הכי ויהי בימי אינו אלא לשון צער ע''כ, החי יתן אל לבו למקשה מפסוק ויהי ביום השמיני והעלים עין ממה שלפניו ויהי ערב ויהי בוקר שממנו למד ויהי ביום השמיני, ולזה יכולני לומר שמקשה משניהם יחד ולהגדיל קושייתו הוסיף גם פסוק ויהי ביום השמיני לומר כי רבים ויהי שהם לשון שמחה, או אפשר שנתכוין לומר לו שאדרבא להפך כל מקום שנאמר ויהי אינו אלא לשון שמחה כדרך שלמד התנא מויהי ביום השמיני מויהי ערב אם כן כל ויהי לא יגרע עינה מזה. גם בזה לא יוכל לדחות כי דבריו הם במן הסתם ולא במקומות שגילה הכתוב בפירוש, כי הרי התנא למד מויהי ערב וגו'. אלא תגדל התמיה על המתרץ, כי מה מתרץ הרי מתו נדב ואביהוא, תירוץ זה מועיל לויהי ביום השמיני ולא לויהי ערב ויהי בוקר שממנו למד ויהי ביום השמיני, ואין לומר שהיה לו איזה ענין לומר שגם בו ביום היה איזה צער, שהרי מצינו כשחזר המקשה והקשה ממנו חזר לאחוריו והודה חצי הודאה. ועוד מעיקרא למה לא נתן לב רבי לוי מעצמו לכתובים שמוכיחים שיש ויהי שהוא שמחה, והיה לו לחלק מעצמו:
@1 **אכן** נראה כי כוונת ר' לוי גם כן לא היתה אלא כדברי רב אשי, ולזה לא אמר אלא אמר רב אשי שיהיה נשמע שסותר דברים הראשונים, שגם יוסבלו דברי רב אשי בדברי ר' לוי, שהרי מקראות ויהי רבים ונכבדים, אלא שהמקשה סבר כי לכל ויהי הוא אומר, ונתחכם להקשות מויהי ביום השמיני כי אין הפרש בין ויהי בימי לויהי ביום, ורצה לסתור הכלל אפילו במקום שיאמר ויהי בימי, והמתרץ תירץ כי שם מתו נדב ואביהוא, כי לא רצה לחלק בין ויהי בימי לויהי ביום, כי אין הפרש, ואין הוכחה מתשובה זו שסובר אפילו ויהי לבד הוא לשון צער, כי לא הוכרח לתרץ זה אלא לצד שהקשה מויהי ביום. ואחר כך חזר להקשות אפילו מויהי לבד, ונתחכם המקשה להקדים פסוק ויהי בשמונים שנה לגלות על ויהי ערב שמלבד שלא היה שם צער היה בו שמחה. והגם שמדברי הברייתא שהביא למעלה מוכח שהיה שמחה לפניו, אינו אלא דברי התנא, אבל אין הוכחה מהכתוב אלא שלא היה צער אבל שמחה מנין, לזה הקדים פסוק ויהי בשמונים שנה שזה ודאי שמחה יגיד בבנין בית המקדש (תענית כו) דכתיב (שה''ש ג') ביום שמחת לבו, וזה יגיד על ויהי כאשר ראה יעקב ויהי ערב וגו' שאינם אלא שמחה, ואמר רב אשי ויהי איכא ואיכא כו', וכן היתה דעת המתרץ ראשון אלא שקדם רב אשי ותירץ. ואולי גם מתרץ ראשון רב אשי הוא והזכיר שמו במסקנא, או ב' סתמי דתלמוד הם, וג' דרכים אלו הם שאנו הולכים בהם בשבילי התלמוד. נמצאת אומר כי אפילו לרב אשי ויהי ביום הוא כויהי בימי, והצער הוא שמתו נדב ואביהוא שאין כמותם בכל ישראל, וזולת זה לא היה אומר הכתוב ויהי, וגם אומרו (יתרו י''ט ט''ז) ויהי ביום השלישי, גם שם הרי פרחה נשמתם של כל ישראל כאומרם ז''ל (שבת פח:) וזולת זה לא היה אומר ויהי ביום:
@1 **ואולי** נראה עוד כי הצער שיגיד הכתוב הוא של משה המוזכר בכתוב כי ראה גדולתו וגדולת זרעו ביד אהרן ובניו, וצא ולמד צער הקנאה מדבר טוב מה עושה ממעשה בניו של שמעון הצדיק (מנחות קט:), וישתנה מה שלפנינו שהיתה לו ולזרעו אחריו, ולצד שהפציר בשליחות פרעה חרה אפו בו ביום ההוא ועזבו מהיות כהן לעולם, וכשהגיע יום הפקידה נצטער על אשר פרח ממנו עוז תפארת כהונת עולם, והגם כי עצם מאוד בצדקות ובענוה, הלא כל לב חי מרגיש ובפרט בדבר מצוה יקרת הערך ומופלאה כזאת. ואולי כי צער זה רמזו הכתוב בפסוק (ז' א') ויהי ביום כלות משה שהוא עצמו יום זה, ומיתת נדב ואביהוא רמז כאן בפסוק ויהי ביום השמיני:
@1 **ביום וגו** ' **קרא משה לאהרן וגו'**. דע כי העושה דבר כזה שיתן גדולה הנודעת לו לזולתו, לו יהיה אחיו, כאשר יתחייב לעשותה, לא ישלוט בנפשו עשותה בג' שלמיות, הא' שיעשנה במהירות, והב' בצירוף בחינת ההדרגות שישנה בדבר. הג' עשיית הדבר בפרסום לפני רבים, והודיע הכתוב כי שלשתם יחד שלט משה בנפשו ועשאם. כנגד המהירות אמר ביום השמיני, פירוש בהיות הבקר טהור לב לא עכב אלא תיכף קרא לאהרן לתת לו הכהונה ולא נתעצל. ב' עשה הדבר בצירוף בחינת ההדרגות שנתן הכהונה לאהרן ולבניו יחד, הגם כי בזה יגדל העצבון בלבו שיראה גדולה מושכת לאהרן ובניו ואשר יעצב אל לבו יעשה הדבר בהדרגות, בתחלה יקרא לאהרן ואחר כך לבניו, כי לא היה הכרח בקריאת הבנים אז עם אהרן. הג' במצב כל הזקנים דכתיב **ולזקני ישראל** לעשות הדבר בפומבי בפני רבים ונכבדים, וזה יורה על שלימות הרצון לעשות רצונו ית', וכפה הרגשותיו:
@2 **קח לך עגל**. ביומא דף ג' דקדקו אחר שאמר ואל בני ישראל וגו' קח לך למה לי מובן הוא שהעגל לו. ודרשו שבא לומר שיקח משלו ולא משל ציבור. עוד נראה לומר כי אומרו לך כי זה יהיה לו לאות עולם כי לא עשה הוא העגל בכוונה ח''ו ולא טעה אחריו אלא שבא על ידו בלא כוונה ובלא מחשבה רעה, ולצד זה יועיל לכפר בעגל, מה שאין כן ישראל לצד שמעשיהם בעגל הוא בחינת המזיד ולא יבא העגל לחטאת להם והוא אדרבה קטיגור. ותמצא (ויק''ר כא) שהקפיד ה' על אהרן לבל יכנס לבית ה' פנימה ביום הכיפורים בבגדי זהב לצד שעשה זהב העגל, ויש להעיר בזה למה צוה ה' שיביא עגל בן בקר לחטאת והלא החטאת באה לכפרה ואין לך סניגור בעולם כזה. ונראה כי האדון ב''ה שפט בצדק הדבר, לצד כי אהרן לא עשה שום פעולה בבחינת מעשה העגל כי לא ציירו ולא הכינו ואין צריך לומר שלא האמין בו ולא טעה אחריו חס ושלום כמאמרו למשה (תשא לב כד) ויצא העגל פירוש מעצמו יצא על ידי מעשה אשר עשו ב' מכשפי ערב רב יינום ויומברוס כמאמרם ז''ל (תנחומא תשא יט), ומעתה המעשה שעשה הוא בבחינת הזהב שאמר להם (שם) למי זהב התפרקו ולקח מידם ויצר אותו בחרט ומעשה זה עשהו בידיעה שלימה והגם שטעמו היה לצד יראה מישראל לבל יהרגוהו כחור, גם היה מאבד להן הזמן עד שיבא משה, אף על פי כן הרי עשה מעשה בלתי הגון, אשר על כן אמר ה' שיביא העגל לכפר על הדבר שיצא על ידו שלא בכוונה אבל הזהב שמעשה שעשה בו היה בכוונת המכוון אמר ה' לא יראה בו לפני ולפנים שלא יעשה קטיגור סניגור, מה שאין כן ישראל שחטאו בעגל אינם יכולין להביא עגל לכפרה לזה צוה ה' שיביאו שעיר עזים:
@2 **עוד** נראה לומר בהעיר איך אנו אומרים (ר''ה כו.) אין קטיגור נעשה סניגור בענין הזהב והלא אמרו (ערכין טז.) ארבעה בגדי זהב של כהן גדול מכפרים על ארבעה מיני עבירות וכו' אם כן קטיגור נעשה סניגור, ובהכרח ליישב כי ישתנה כפרת חוץ מכפרת פנים שכפרת פנים מלבנת החטאים כשלג, וזה לך האות לשון של זהורית (יומא סז.), ודבר זה הוא מופלא וצריך שלא ימצא בו רושם העון כלל, ואשר על כן הבגדים להיותם בחוץ מכפרים הגם היותם מין זהב מה שאין כן כפרת פנים, וגם לפי חילוק זה ישתנה חטא של אהרן בזהב מחטאם של ישראל בעגל, כי אהרן מכפר בחוץ בבגדי זהב וישראל אינם מתכפרים בעגל כי חטא אהרן בזהב שוגג גמור היה בלקיחתו ובנתינתו בחרט מה שאין כן ישראל, ולזה לא יתכפרו בעגל אפילו בחוץ והבן:
@3 **תדבר לאמר**. צריך לדעת מה טעם ידבר כאן אהרן לישראל ולא משה הרגיל ואולי כי לצד שאמר להם למי זהב התפרקו וגו' לזה יצו ה' אליו כי ידבר להם להביא כפרה שעיר עזים הפה שאסר הוא הפה שהתיר וכבר כתבנו בכמה מקומות דברי רז''ל כי החטא יפעיל הגנאי במקומו והתיקון צריך להיות מכוון כנגדו והוא אומרו **תדבר לאמר** פי' תדבר דיבור שיש בו מעלה וזכות כנגד דיבור שהיה בו השפלה אשר פרע בו את העם. עוד נראה כי לצד שעלה אהרן במעלה הנפלאה הלז מתוך כל ישראל בו בחר ה' לז''א אליו משה שידבר לישראל אמירות רכות והוא אומרו **לאמר** וכן תמצא שאמר **כי היום ה' נראה אליכם** פי' כל המושג וכל הרצון אינו אלא לצד ישראל כאומרו אליכם ולא לי וכדרך שמצינו שאמר משה לישראל הלא כ''ז שהיו ישראל נזופים לא דבר ה' עם משה כי כל המושג אינו אלא לצד מעלת ישראל:
@5 **ויקחו וגו' אשר צוה משה**. אמר **אשר צוה משה**, יכוין אל אהרן גם כן שלקח את אשר צוהו, ואינו יוצא ממשמעות מעשה ישראל שהגם שמפי אהרן נאמרו להם הדברים אהרן עצמו מפי משה אמרם, ואילו אמר הכתוב אשר צוה אהרן אין במשמע אלא לקיחת ישראל ולא לקיחת אהרן. עוד אולי שנתכוין באומרו **אשר צוה משה** כי לצד מצות משה לבד עשו הדבר הגם שלא היתה ההבטחה הרשומה במאמר:
@6 **זה הדבר וגו'**. צריך לדעת מה הוא **הדבר**. ורש''י פירש על הקרבת אהרן. ואין זה פשט מאמר הכתוב שאמר תעשו ונראה שיכוין לומר על המעשה שהזכיר הכתוב בסמוך דכתיב ויקרבו כל העדה ויעמדו **לפני ה'**, דקדק הכתוב לומר **לפני ה'** ולא אמר לפני אהל מועד גם לא היה צריך לומר שהרי אמר בסמוך ויקחו וגו' אל פני אהל מועד, אלא ירצה לומר שהכינו עצמם בערך השלימות והמושכל והערכת עמידתם שהיא לפני ה', ובחינה זו היא השגת תכלית השלימות, כמאמר דוד (תהלים טז) שויתי ה' לנגדי תמיד כי בזה לא ימוט מימינו שהיא התורה, כי אין ישיבת האדם ותנועותיו וכו' כישיבתו וכו' לפני מלך ומכל שכן לפני מלך מלכי המלכים, וכשהשכיל משה במעשה זה אמר להם זה הדבר אשר צוה ה' תעשו פירוש צוה ה' שתעשו אותו, שתהיו תמיד מעריכים בדעתיכם כי אתם עומדים לפני ה', וידא אליכם כבוד ה' עוד יכוין בכלל אומרו **לפני ה'** שלא היה מסך מבדיל בינם לבין ה' כדכתיב (ישעי' נט) עונותיכם היו מבדילים וגו', וזה יגיד שהיו שלימים עם ה' וכפי זה ידוייק על נכון אומרו זה על מעשה האמור בסמוך:
@6 **אחר** שכתבתי זה בא לידי מדרש חז''ל (במד''ר נשא פי''ב ח') וזה לשונם זה הדבר מה הוא זה הדבר על המילה כמה דתימא זה הדבר אשר מל יהושע עד כאן. ודברי המדרש סתומים וחתומים, וכי באותו יום מל אותם משה, או באותו יום צוה על המילה:
@6 **אכן** הכוונה היא על ערלת לבם שהוא דבר המבדיל בין ישראל ובין אביהם שבשמים, גם מרחיק אימתו מלבם, וצוה למול ערלת לבבם ובזה יראה להם כבוד ה', והם דברינו עצמם. שוב באה לידי מדרש אחר (כן הוא בתו''כ הכא) בילקוט וזה לשונם זה הדבר אמר להם משה לישראל אותו יצר הרע תעבידו מלבבכם ותהיו כלכם ביראה אחת ובעצה אחת לשרת לפני המקום וכו' ותהיה עבודתכם מיוחדת לפניו דכתיב ומלתם את ערלת לבבכם וגו' ואם עשיתם זה וירא אליכם כבוד ה' עד כאן, והם דברינו עצמם:
@7 **וכפר בעדך ובעד העם**. משמע כי כפרת אהרן נוגעת גם לעם. והטעם הוא לצד כי חטא אהרן ישראל היו לו סיבה לחטוא שאמרו לו (תשא לב א) קום עשה לנו וגו', וכל עוד שלא נתכפר אהרן ישנו החטא לעושהו ולמסבב עושהו, ואחר שנתכפר נתכפרו שניהם, לזה אמר לו וכפר בעדך ובעד העם:
@8 **ויקרב אהרן אל המזבח**. ירמוז לדבריהם ז''ל שאמרו (ירושלמי מכות פ''ב ה''ו) שאלו לנבואה חוטא מה עונשו אמרה הנפש החוטאת היא תמות, ולצד רחמי ה' אמר יביא קרבן, שעיקר מעשה הקרבן היא מחשבת המקריב כי הוא החייב בכל המעשה אשר יעשה בקרבן ההוא ליזבח ולהשרף על האישים והיתה לו מחשבה זו לכפרה, והוא אומרו **ויקרב אהרן אל המזבח** פירוש הוא עצמו הכין לשום אשם נפשו, וקרב למזבח פירוש לזביחה לאישים, ועשה השחיטה במקומו לעגל לצד רחמי ה' שנתרצה להביא חליפתו:
@8 **וראיתי** לתת לב בענין לפי מה שקדם לנו (תנחומא שפטים) כי נשבע ה' להעמיד העולם וברואיו במשפט, וכל האומר הקב''ה וותרן יוותרו בני מעיו (ירושלמי שקלים פ''ה ה''א), אם כן אם הנפש החוטאת משפטה היא תמות כמאמר הנביא (יחזקאל יח ד) איך יביא קרבן ויפטר, ונראה כי טעם נכון יש בדבר על פי המשפט, כי כשהאדם חוטא אין בחינתו בחינת ארם, על דרך אומרם ז''ל (סוטה נ. ג.) אין אדם עובר עבירה אלא אם כן נכנס בו רוח שטות, ונעשה בהמה וביום שחזר בתשובה רוח היא באנוש ועלה ממדריגת בהמה למדריגת אדם, האם ראוי הוא להמית אדם זה תחת בהמה, לזה יביא דוגמת החוטא שהוא בהמה וישתתף עמה בצער החושב כי ראוי הוא לעשות בו משפט זה, וכפי זה חלק רוח המרגיש הוא מציל את האדם בהערה זו, והוא מה שאמר הכתוב (תהלים לו) אדם ובהמה תושיע ה' כי חלק הבהמי שבאדם בהצטרפותו עם האדם שהיא בחינת ההשכל נושע בו פירוש לצדו כדי שלא יענש והוא אינו ראוי לעונש, ובזה אפילו בדין הקרבת הקרבן בעד החטא הוא על קו המשפט, כאומרו (שם) משפטיך תהום רבה אדם ובהמה תושיע ה':
@15 **ויקרב את קרבז העם**. זו הקרבת בחינת האורות הנטועות בישראל ממקור האור אשר נשתנו באמצעות החטא ולא יהיו בבחינת הנשתוון להתקרב, כי השינוי בנפש יחייב ההרחקה, כי יעשה שאינו מינו, ובאמצעות העבודה שעשה אהרן יגיד הכתוב כי הקריב קרבן העם פירוש שהקריב כל הרחקותם. והנה מהראוי היה שיכתוב פסוק זה בסוף מעשה הקרבן, וטעם שהתחיל בו, לומר שהפעולה נעשה במה שכוון במעשה קודם עשוהו, כי לא המעשה הוא העיקר אלא הכוונה הצריכה בו והוא אשר עשה אהרן בתחילת מעשיו והבן. וארמוז לך פרט אחד קטן שרמז הכתוב באו' **ויקרב את העולה ויעשה כמשפט**, כבר רמזתי לך כי זכרון העולה ירמוז על כנסת ישראל ובאמצעות הרחקת ישראל מהיושר הם מורידים העולה למטה ח''ו ובאמצעות התקרבותם לא מלבד שלא תשולח בפשעם אלא יוסיפו להעלות עליה אחר עליה עד שתעמוד בגדר המשפט כידוע למשכיל, והוא ויעשה כמשפט. שמעתי:
@22 **וישא אהרן וגו'**. בתורת כהנים פרשה כ''ט אמרו מקרא מסורס ראוי לומר וירד מעשות וגו' וישא אהרן וגו' שבירידתו נשא כפיו וכו'. וצריך לדעת למה ידבר הכתוב בדרך זה ולא בדרך הישר. ואולי כי בראותו אהרן שלא ירדה שכינה חשב אולי כי עדיין חסר כפרתו על מעשה העגל שבאמצעותו הביא קללה על שונאי ישראל, ולזה וישא וגו' ויברך וגו', ובזה ירד מעשות תשלומי החטאת וכו' ואולי כי גם ברכת ישראל לצד שהיא כפרת חטאו של אהרן תוכלל בכלל החטאת, כי גם לה יתיחם שם חטאת, ואומרו **וירד**, אולי כי הוא לשון ירידה כי הוכר לו פחיתותו, לצד שראה שגמר מעשות הכל ולא ירדה שכינה, ותמצא שאמרו ז''ל בתורת כהנים פרשה י''ט שצעק אהרן לפני משה שאמר לו ליקרב למזבח ובא לידי בושה וכו' ונכנס משה עמו ובקשו רחמים וירדה שכינה:
@23 **ויצאו ויברכו וגו'**. אולי כי כן נצטוו בנבואה. או ברכה זו במקום תפלה היתה כדי שתשרה שכינה. והגם שכבר בירכם אהרן, טובים השנים לצד הסכמת ב' מדרגות הרמוזים בב' בחינות האחים כהונה ולויה שהם חסד וגבורה:
@25 **ויקחו בני אהרן נדב ואביהוא וגו'**. ירצה להודיע מקום טעותם שהיא לב' סיבות, האחד להיותם כהנים שאליהם תאות העבודה וזהו שהתחיל לומר בני אהרן, ב' היותם גדולים במעשה ושקולים הם כמשה ואהרן כאוז''ל (תו''כ הכא אחרי נג) וכאומרם בספר הזהר הקדוש (אחרי נו) שהיו במדרגה גדולה מצד מעשיהם, וזה אומרו נדב ואביהוא, ובחינ' זו אינה באלעזר ואיתמר שהגם שהם בני אהרן אין להם מדרגה מצד עצמם כנדב ואביהוא, וכן תמצא שדרשו ז''ל (תו''כ להלן פסוק טז) במה שכתוב ויקצוף משה על אלעזר וגו' הנותרים וגו' יעויין שם דבריהם ובכח זה נכנסו, ודקדקו ליכנס שניהם יחד להגדיל זכותם, ולא רצו לקחת מאש המזבח, אמרו אולי אין ראוי לקחת ממנה אלא לקטורת החיוב, לזה הביאו מבחוץ:
@25 **וישימו עליה**. ולא אמר עליהן כאומרו ויתנו בהן וגו', וישימו עליהן, חוזר אל האש שהזכיר בסמוך, להיות שהקפדה היא על אש זרה לזה כינה בה המעשה:
@25 **זרה אשר לא צוה**. פירוש ומה היא זרותה, שלא צוה ה' אותה. ואולי שאם היו לוקחים אש מעל המזבח לא היה ה' מקפיד על הדבר כל כך. או אפשר שהיה מקפיד מאופן אחר. עוד ירצה על זה הדרך אש זרה אשר לא צוה אותם לעשות כן וזה היא זרותה:
@26 **וימותו לפני ה'**. אולי שירמוז טעם מיתתם, שהוא להפחיד לירא מן המשכן בראותם את אלו שקרבו לפניו מתו, עוד ירמוז כי מיתתם היה על מה שקדם מהם לה', על דרך מאמרם ז''ל (ויקרא רבא פי''ג) שמיתתם היה למה שקדם ויחזו את האלהים וגו', והם הם אצילי בני ישראל:
@27 **הוא אשר דבר ה' וגו'**. צריך לדעת כוונת אומרו **הוא** ב' אומרו לאמר משמע שצוה ה' לאמר אם כן למה לא אמר עד עתה, ושגיון זה דומה לשגיון אזהרת שבת שלא צוה בשעתו עד אחר כך אמר (בשלח טז כג) הוא אשר דבר ה', ושם מצינו לו טעמים מספיקים בענין כי לא נאמר לו לאמר כמו שדקדק לומר הוא אשר דבר ה' שבתון וגו' ולא אמר לאמר, מה שאין כן במה שלפנינו שאמר לאמר, ורז''ל מצינו להם שאמרו (תו''כ הכא) היה אהרן עומד ותוהא ואומר אוי לי כך עבירה בידי וביד בני שכך הגעתני, נכנס משה אצלו והיה מפייסו אמר לו אהרן אחי מסיני נאמר לי עתיד אני לקדש הבית באדם גדול והייתי אומר או בי או בך הבית מתקדש עכשיו נמצאו בניך גדולים ממני וממך וכו' עד כאן. דבר אחר ויאמר משה וגו' הוא אשר דבר וגו' דיבור זה נאמר למשה בסיני ולא ידעה עד שבא מעשה לידו וכיון כו' אמר לו משה לאהרן לא מתו בניך אלא בשביל קדושת שמו של מקום שנאמר (תצוה כח מג) ונועדתי שמה לבני ישראל ונקדש בכבודי, כיון ששמע אהרן שבניו ידועי המקום הן שתק ע''כ:
@27 **הנה** לדרך הראשון מפרש תיבת **הוא** על זה הדרך להיות שהיה מצטער על הסיבה שהוא סבב לבניו שמתו לזה אמר לו משה כי הוא זה טעם מיתתם לצד אשר דבר ה' וגו' ולא לצד עונו היה הדבר, ותיבת הוא כפי זה חוזרת אל הסובב. ולדרך ב' תיבת **הוא** חוזרת אל הדיבור הסתום שלא ידעו ועתה ידע כי הוא זה מכוון הדיבור הנאמר לו קודם ונקדש בכבודי, גם לא נאמר לו שם דבר ולא לאמר דוק ותשכח, ונשארו הדברים בלבב משה סתומים עד שעת מעשה והבינם ואמר הוא אשר דבר ה' אלי ומה דבר ונקדש בכבודי. ואומרו **לאמר** וגו' פירוש כוונת דברי ה' באומרו ונקדש בכבודי הוא לומר על זה הדרך באומרו ונקדש רצונו לומר בקרובי אקדש, ואומרו בכבודי הוא ועל פני כל העם אכבד, ולדרך זה נתישבו כל הדקדוקים. אלא לדרך ראשון עדיין קשה מה שהקשינו. ולעמוד על עומק דבריו יש להעיר אומרו או בי או בך שלא היה לו לומר אלא בי או בך או יאמר בך או בי כי לא יוצדק לומר או בתחילה:
@27 **ולזה** נראה לישב כי לצד שיש בענין ב' דברים. הא' הוא בחינת המעלה והב' בחינת המאורע שהוא המיתה, וכשבא לומר את אשר הבין מי הוא הקרוב אשר יקדש בו אם היה מתחיל לומר בי או בך היה נשמע בדבריו כי הוא הקרוב לפני ה' ביותר מעלה וכבוד ולזה הזכיר עצמו בפשיטות והזכיר אהרן בספק או, לזה אמר או בי שגם הוא בספק ואם היה אומר בך או בי יבא המיחוש כי רצה להלביש המאורע הרע באהרן כי הוא ימות בהשראת שכינה ואת עצמו עשה בספק, לזה נתחכם משה ואמר או בי הקדים עצמו לצד בחינת קבלת הפורענות ולא בהחלט כדי שלא יכנס בחשד כי מעריך עצמו בערך גדול מאהרן ואמר או דרך ספק כדרך הספק שעשה באהרן באומרו או בך. אלא שעדיין קשה כיון שלא נאמר מה' אלא א' מהם ולא נכנס לו הספק אלא איזה א' מהם אם כן למה מתו שנים, ועוד מנין לו לומר שהם גדולים ממשה ואהרן כיון שלא אמר ה' אלא א' מהם ומתו שניהם נכנסו במקום א' מהם, ואינו יכול לומר אלא טובים הב' מאחד מהם. אכן הכוונה הוא שכשאמר לו ה' ונקדש בכבודי ידע משה כי ימות מהצדיקים, אלא שסבר בשיעור משמעות הדברים באומרו ונקדש בכבודי הוא שיתקדש הבית באותו שהוא כבודי מכובדי שהוא הצדיק. ולפי זה אין כאן אלא צדיק א' כי כן משמע כבודי לשון יחיד ונפל לו הספק מי הוא זה היחיד אם הוא משה אם הוא אהרן, והוא אומרו או בי או בך וכמו שפירשנוה, ועכשיו כשראה כי מתו שנים חזר להבין כוונת אומרו ונקדש בכבודי שאין הכוונה שיתקדש ובמה בכבודי שהוא לשון יחיד, אלא הכוונה הוא על זה הדרך בקרובי אקדש והוא אומרו ונקדש, ואומרו ועל פני כל העם אכבד הוא כוונת אומרו בכבודי פירוש בשביל כבודי, וכפי פירוש זה לא אמר ה' לשון יחיד בצדיקים כי הצדיקים נרמזו באומרו ונקדש, ואומרו בכבודי הוא בשביל כבודי, והראיה שכך הוא כוונת אמירתו יתברך שהרי מתו שנים והוא אומרו הוא אשר דיבר תשובה לאהרן שלא יתעצב וכו' ופירש דברי ה' שהם לאמר פירוש כוונת אמירתו היא על זה הדרך בקרובי וגו' ועל פני וגו' לשלול פירוש אחר שיתחייב ממנו לומר שלא ימות אלא אחד:
@27 **או** אפשר שמשה הבין גם כן דרך זה שאמר כאן בקרובי וגו' ועל פני וגו', והוא מה שרמז בדבריו או בי וכו' כי אומרו או יגיד שקדמה חלוקה אחרת והוא שניהם יחד והוא דרך שצדק לבסוף, או בי לבד, או בך לבד, ואחר מעשה הוכרע ספק השקול שכוונתו לאמר בקרבי וגו' ועל פני וגו' ולזה מתו ב'. ובזה נתיישבו הדקדוקים שדקדקנו בכתוב. ונשאר ליישב מכל מקום מי אמר למשה להכריע כן דלמה לעולם הכתוב כפשוטו ונקדש הבית בצדיק א' הנרמז בתיבת כבודי ומה שמתו ב' כי זכות שניהם מתאים לשיעור א' מהם משה או אהרן הנה בהשכיל על טעם הדבר נדע שאין זו קושיא, כי טעם הדבר הוא לצד שחש ה' שכשראו ישראל את אלהיהם שכן שמו בתוכם ואין גדולתו ומוראו ניכר כסדר שהוא ניכר בעליונים שלא יהיה מוראו עליהם כמצטרך ולא יתנהגו כשיעור הכבוד המתחייבים בו, ויותר יש לחוש לגדולי ישראל שיחשבו בדעתם שהם קרובים אל ה' וירצו להיות נגשים ומתקרבים, אשר ע''כ עשה משפט בגדול שבכולן שאין גדר למעלה ממנו לחוש לו לומר שבערך בחינתו לא תמנע ממנו הקריבה לה', ונשאר כל העם שומרים כבודו יתברך כאומרו ועל פני כל העם וגו'. ומעתה לכשנאמר כי משה בפני עצמו גדול מנדב או אביהוא אהרן בפני עצמו גדול מכל א' מהם גם כן, אם כן הניח ה' הדרגה שאין עליה מורא, ולצד התחברותם, הלא לא יועיל זכותו והשגתו של א' לחבירו להכינו לאושר להתקרב לשכינה, ואין הגבלת כבוד לה' אלא לגדר של כל א' מהם ולא לגדר גדול מא' מהם. ולכשנכחיש בחילוק זה ותרצה לומר כי יצטרף זכות ב'. אם כן עדיין יחסר הגדלת כבודו יתברך בערך משה ואהרן יחד, או שלשה כנדב ואביהוא, או ה' שיצטרף זכותם ליותר מזכות נדב ואביהוא, אלא ודאי כי לא יצדיק הצירוף כאן. ועוד תמצא שאין נערך זכות הנפרד לזכות הנסמך בבחינת המרגליות ואבנים טובות, שב' קטנים הגם שיהיו גדולים בהצטרפותם יחד מאחת גדולה לא תכנם עמהם הגדולה בהשוואת הערך, והדברים פשוטים:
@30 **ראשיכם אל תפרעו וגו' ועל כל העדה וגו'**.
@30 פירוש אם יעשו כמותכם, שאתם דוקא הוא שישנם באזהרה, אבל על כל העדה יקצוף אם יעשו כן, אלא חייבין לקרוע עליהם. ואולי ששפט בהם משפט אב בית דין שחייבין לקרוע עליו כל ישראל (מועד קטן כב:). ומה גם למה שאמר שהם גדולים ממשה ואהרן חייבים כל ישראל לקרוע עליהם. ואומרו **ואחיכם** וגו' **יבכו**, למצוה, ואם לא בכו אין עליהם קצף כמשפט הקריעה. ודקדק לו **אשר שרף ה'**, יתבאר על דרך אז''ל (שבת קה:) שכל הבוכה ומתאבל על אדם כשר מוחלין לו כל עונותיו ולא יבכה עוד, והוא מה שרמז באומרו אשר שרף וגו' פירוש אם יבכו השרפה אין להם אלא מה שכבר שרף מקודם לשלול שלא תהיה שריפה אחרת עוד. עוד ירצה באומרו **ולא תמותו ועל כל** וגו' פירוש כי באמצעות מיתת הצדיקים מגיע קצף לכללות ישראל, כי חוזק ישראל וחיותם הם גדוליהם הצדיקים ובפרט כהני ה' המכפרים בעד העם:
@40 **דרש דרש משה וגו'**. אומר אני כי משה לא החליט בדעתו להתירו באכילה, והראיה ממה שלא אמר להם דינו כמו שאמר להם במנחה (פסוק יב) קחו את המנחה וגו', שאם היה בדעתו בפשיטות להתיר היה לו לומר קחו את החטאת, מה תאמר שאמר דין המנחה וחשב כי אין הפרש בינהם כל עיקר ולרוב פשיטות שהיה לו הדבר לא הוצרך לומר אם כן לא היה לו לדרוש כי מנין נכנס לו המיחוש לדרוש עליו מה היה בו, אלא ודאי שלא אמר אלא הפשוט אצלו שהיא המנחה שהיא קדשי שעה וממנה לשעיר נחשון ושעיר עזים שהיו קדשי שעה, אבל שעיר ראש חודש שהוא קדשי דורות עדיין היה הדבר עומד אצלו בספק והיה דורש בדעתו אם יתירנו כמו כן או לא, ודרש עליו מה היה בו, ולזה כפל לומר **דרוש דרש** אחת למשפטו ואחת לעצמו מה היה בו והנה וגו' ויקצוף על אשר עשו דבר מדעתם שאפילו הוא עדיין לא ידע את אשר יצוה להם עשות. והגם שאמר לבסוף תאכלו אותה כאשר צויתי, פירוש יותר היה לכם לדמותה למנחה אשר צויתי לאוכלה ולא לשורפה בלא טעם הפך מה שצויתי במנחה. ובתורת כהנים אמרו דרש דרש מפני מה נשרף, ומפני מה (לא) נאכלו אלו, ובישוב הכתוב הדברים רחוקים, כי אחר הדרישות הוא שנגלית השריפה, ואיך ידרוש קודם למה נשרף. ויש לישב:
@40 **הנותרים לאמר**. אומרו **לאמר**, יתבאר על דרך אומרם ז''ל (ויק''ר פי''ג) הנותרים אמר ר' פנחם ולואי שלא נשארתם ע''כ. והוא אומרו הנותרים לאמר פירוש הנותרים לאמר ענין אחר, והוא דברי ר' פנחם, ובתורת כהנים אמרו לאמר אמר להם השיבוני על דברי פירוש הרשם להשיבו שלא ימנעו לצד ראותו בקצף עליהם עוד ירצה על דרך אומרם ז''ל (ב''ר פע''ג) בפסוק צאן לבן הנותרות שהוא לשון פחיתות, והוא אומרו **הנותרים לאמר** כאילו אמר לאמר הנותרים פירוש קראם במאמרו נותרים לשון פחיתות:
@43 **וידבר אהרן אל משה**. רז''ל (תו''כ) אמרו אין דיבור אלא לשון עז, יורה על דברים קשים. צריך לדעת איך יוצדק ענין זה באהרן עם משה. ואולי כי לצד שאמר משה לבניו הנותרים שהוא דבור דומה לקללה והוא עדיין בחרדת לב על ב' בניו שכבר מתו בו ביום והשטן מקטרג. ומה גם כששמע עקימת שפתיו של משה בדמיון הקללה, לזה חרד לבו ודבר בקול גדול לפני משה כי נכמרו רחמיו אל בניו:
@43 **הן היום**. רז''ל דרשו (זבחים קא.) שרצונו לומר וכי ביום זה הקריבו אלעזר ואיתמר שאסורים להקריב באנינות שאתה אומר שמא הקרבתם אותו באנינות ולזה שרפתם, אני הוא שהקרבתי וכהן גדול מקריב אונן. ופשט הכתוב הוא על זה הדרך **הז היום הקריבו** פירוש נדב ואביהוא את חטאתם ואת עולתם לפני ה' וכו', שכוונתו כי הוא אונן כי בו ביום מתו, **ואכלתי חטאת היום** פירוש חטאת של יום שהוא שעיר ראש חודש, וכאן רמז לו שישתנה זה ממנחה שהוא קדשי שעה אבל חטאת היום הוא קדשי דורות הייטב בעיני ה' לאוכלו. והיה נראה להוכיח מכאן ספק א', אם מותר לתלמיד להורות לעצמו הוראה במקום רבו, שראיתי להרא''ש ז''ל (עירובין פ' הדר) שכתב לאסור זולת סר סכינא שאין קפידא כל כך. והנה ממה שראינו שהורה אהרן הלכה זו לעצמן ושרפו החטאת משמע שמותר. ואין לך רב מובהק כמשה לאהרן. ואולי יש לדחות, כי אין הוראה זו הוראה, כפי מה שאמרו ביומא (רש''י שם דף ה:) שדן אהרן קל וחומר ממעשר הקל אמרה תורה לא אכלתי באוני קודש חמור לא כל שכן ע''כ. וכיון שנאמר לו מפי משה דין מעשר כאלו אמר לו משה לשרוף ולא הורה הוא לעצמו כלום, כי בכלל מעשר חטאת בקל וחומר וכגון זה מותר לתלמיד להורות, וקל הוא מביעתא בכותחא. ועיין בדברי התוספת שם (עירובין סב:) פירוש הוראת ביעתא בכותחא:
@44 **וישמע משה וייטב וגו'**. יש לדעת איך נתעלמה ממנו הלכה פשוטה כזו לחלק בין קדשי דורות לקדשי שעה. ואם היה לו איזה צד לומר שאין לעשות חילוק זה, למה קבלו מאהרן ולא דן עליו לסותרו. והנה לפי מה שפירשתי למעלה כי גם משה היה צריך לעמוד על הדבר אם לאכלה אם לשרפה, ולא היה לו מוחלט הדבר לאכילה והקפדתו על אהרן ובניו היתה לצד שחשב ששרפוהו בלא טעם נכון, או לצד שמא אירע לה איזה מאורע כמאמר רז''ל (פסחים סב. זבחים קא) שאמר להם שמא אירע בו פסול בהקרבת דמו או נטמא או יצא חוץ למקומו, וכל אלה הדברים הם לצד מיעוט זריזותם, ועל זה היתה ההקפדה, מה שאין כן אחר שאמר לפניו אהרן הדין שדן בו ושרפו קבל משה הטעם וראה שלא שרף אלא אחר שדן דין צדק, ואין הכי נמי אם לא היה דן אהרן והיה דן משה כזה היה דן בדבר ושורפו, ולא יבצר ממנו כל דבר, ואומרו **וייטב בעיניו**, פירוש את אשר עשו בשריפתו, ולא הקפיד על אשר סמכו על עצמן ולא שאלוהו:
@44 **או** ירצה **וייטב בעיניו** אהרן כי טוב הוא ויורה יורה ידין ידין:
@44 **או** ירצה **וישמע משה** פירוש התורה מעידה שחילוק זה שמעו משה מפי הקב''ה, **וייטב בעיניו** הדבר אשר עשה אהרן. ואם תאמר אם שמע כן מפי הקב''ה מה מקום להקפדתו. אולי לצד שלא אמרו עדיין לאהרן חש שדן בו טעם אחר שאינו צודק ושרפו, או אפשר כי באותו שעה נאמרה לו נבואה זו, כי מצויה היתה נבואה למשה, כאומרו (במדבר ט ח) עמדו ואשמעה מה ידבר ה', וכמו כן כאן תיכף וישמע משה מפי ה' המשפט וייטב בעיניו אשר צדק אהרן במשפטו. ורז''ל אמרו במדרש (תו''כ כאן) וזה לשונם אמר רב יהודה חנניה בן יהודה היה דורש כל ימיו קשה ההקפדה שגרמה למשה לטעות, אחר מיתתו אני משיב לו על דבריו, וכי מי גרם לו שהקפיד אלא שטעה ע''כ. טעם אומרו כל ימיו, גם טעם חנניה שלא אמר כרב יהודה שהוא היותר מובן מפשטי הכתוב, גם טעמו של רב יהודה שלא חלק אלא אחר מותו יראה כי חנניה ורב יהודה כל אחד מתכוין לדבר טוב על משה, לצד שיש לפנינו ב' דרכים. הא' השכחה אשר אמר לו ה' והוא שלא מן המוסר לנאמן בית, ב' שנתכעס על בני אהרן ודבר להם קשות כנזכר, וגם לצד אהרן קצף בדרך נסתר. ובא חנניה ובחר לתלות כמשה שגיון הכעס ששגג בו והוא סיבה לטעות מלומר ח''ו ששכח דבר ה' שהוא דופי גדול. וכמו כן מצינו בספרי (מטות פסוק נז) שאמר ראב''ע בג' מקומות בא משה לכלל כעם ובא לכלל טעות וכו', כיוצא בדבר ויקצוף משה על אלעזר וגו' ע''כ. מכאן אתה למד שהדבר שעליו הקפיד לא (מצד) הטעות. ואם תאמר אם כן למה הקפיד אם לא טעה, בהכרח לומר שהקפיד על אשר דנו בדעתם וסמכו על הוראתם מבלי שאלת רבם, ועל זה נתעלמה הימנו הלכה ואמר אכל תאכלו, וסובר כי בהחלט הוא אומר כפי הדין שראוי לאכלה, לא כמו שפירשתי שאין דבריו בהחלט אלא שאומר צד הנגדי למעשיהם, ובא רב יהודה וחלק כי אין לתלות במשה ההקפדה בהחלט, כי יש בהקפדה צד לומר שהיא גרועה מהעלם דבר ואפשר לתלות שטעה ושגג בדין ולצד שגיונו הקפיד על המעשה שנעשה שלא כרצונו יתברך אבל זולת הטעות לא יקפיד על כבודו. והנה דעת זו לא היתה מוכרעת לרב יהודה אלא שקולה, שיש פנים להקל בבחינת ההקפדה, ויש פנים להקל בבחינת הטעות, ולזה לא חלק על חנניה אלא אחר מותו שעמד בדרשה זו ולא אמר פן האחר שישנו במשקולת ההשכל, משמע כי מוכרע אצלו הדבר כי הקפיד ובזה חלק עליו, ולזה דקדק לומר אחר מיתתו אני משיב. ובנוסח ספרא שלפנינו אמרו הריני כמשיב על דבריו, וממה שאמר כמשיב משמע ולא משיב, ויכוין ג''כ לדברינו. או אפשר לומר כי רב יהודה בחר בהחלט לומר טעמו של משה הוא לצד שטעה מלומר שהקפיד שהוא מעשה בלתי הגון, כי הטעות יכול אדם לטעות בהסח הדעת, מה שאין כן ההקפדה שהוא מעשה מזיד, ועוד אם נאמר שטעה הרי לא יצתה תקלה מטעות, ואם נאמר שהקפיד הרי יצתה תקלה מתחת ידו שהרי הקפיד ונתכעס, ולזה בחר רב יהודה לומר מי גרם לו שהקפיד אלא שטעה. וטעם אומרו אחר מותו, לומר שאפילו כל ימיו דרש ואפילו כבר מת הדורש לא נמנעתי מלחלוק לצד אמיתות הדבר אצל, או נתכוין לומר שלא חלק עמו בפנים ושתק אלא לאחר מותו שאפשר שאם היה בחיים חיותו היה משיב על הדבר להוכיח כמותו ורז''ל אמת יהגה חיכם:
@45 **אל משה ואל אהרן**. אמר **ואל אהרן**. אולי שנתכוון לעשות שניהם יחד שליחות מצוה זו אל ישראל, וכן גמר אומר **דברו אל בני ישראל**, וכן אמר בפרשת בא (יב א) אל משה ואל אהרן וגו' דברו וגו', כי לענין הקדמה שיקדים משה לומר לאהרן קודם ישראל כבר למדנו זה ממקום אחר:
@45 **לאמר אליהם**. רז''ל אמרו (בתו''כ) אליהם פירוש שיאמר לאלעזר ולאיתמר והכוונה בזה כדי להקדימם בלימוד קודם כדתניא (עירובין נ''ד) בסדר הלימוד. ואולי שנתכוון להצריכם להורות בני ישראל על דרך (מלאכי ב) כי שפתי כהן וגו', ואשר על כן סמך לזה דברו וגו'. עוד יתבאר אומרו **לאמר אליהם** לפי מה שפירשתי במקומות אחרים (יתרו כ א) כי טעם אמרו לאמר כי הדיבור היוצא מפי אל עליון היה נוצר ממנו מלאך והוא היה מדבר עם משה, ופירוש לאמר הוא הדיבור יאמר למשה, וכמו כן אמר כאן לאמר אליהם פירוש הדיבור יאמר למשה ולאהרן. ואין פירוש זה מכחיש דברי רז''ל שאמרו (תו''כ א) לא היה הדיבור אלא למשה ולא לאהרן, כי גם לדרכינו לא היה שומע דברי ה' אלא משה, אלא שהמלאך המתהוה מהדיבור היה מדבר לשון רבים, ומשה היה מגיע הדברים לאהרן:
@46 **אל בני ישראל לאמר**. אמר תיבת **לאמר** ירצה כי מצוה זו היא בחינת המעלה והכבוד להם, להשמר מדברים הטמאים, וכאומרם בזוהר (ויק''ר פי''ג) אמר רבי שמעון בר יוחאי בפסוק (חבקוק ג) עמד וימודד ארץ מדד ה' את כל האומות ולא מצא אומה שהיא ראויה כו', ופירוש תיבת לאמר כאן הוא על דרך (ישעי' ג') אמרו צדיק וגו'. עוד ירצה על זה הדרך לאמר זאת וגו' פירוש שיקחו בידם כל מין חיה ויאמרו להם זאת תאכלו וזאת לא תאכלו, ולא יספיק לומר להם בעל פה:
@46 **זאת החיה וגו'**. טעם שמכנה שם חיה בהמה, כבר כתבתי בכמה מקומות כי בחינת הרע לא יתייחס אליו בחינת החיים, והוא אומרו **זאת החיה** פירוש שיש בה בחינה הנקראת חיה, לשלול שאר בהמות שאין להם קדושה שהיא בחינת החיים:
@47 **כל מפרסת וגו' מעלת גרה**. יתבאר על דרך אומרם ז''ל (חולין נט.) כל בהמה שמפרסת פרסה היא מעלת גרה, חוץ מן החזיר, והוא אומרו **כל מפרסת** וגו' **מעלת גרה**, פירוש בידוע שהיא מעלת גרה, ומיעט אחר כך החזיר שיצא מהכלל. ואולי ממה שלא הוציא מן הכלל סמוך להודעת הכלל רמז שאפילו החזיר בכלל, על דרך אומרם ז''ל (רבינו בחיי בשם תנחומא) למה נקרא שמו חזיר שעתיד לחזור להיות מותר, ומעתה כלל כל מפרסת וגו' היא מעלת וגו' לא יצא מכללו דבר, ועל זמן מהזמנים אמר החזיר שהוא מפריס וכו' לא יגר:
@48 **ממעלי וגו' וממפריסי וגו'**. רז''ל אמרו (תו''כ בכורות ו) שבא לאסור אפילו מעלה ומפריס אם נמצאו במעי טמאה. ופשט הכתוב הוא על זה הדרך ממעלי הגרה זה הגמל, וממפריסי וגו' זה החזיר, או זה או זה קאמר, ולזה דייק לומר וממפריסי וגומר, ולא אמר ומפריסי, והבן:
@50 **ואת הארנבת**. טעם זכרון המין בלשון נקבה לצד שבחינת הטומאה לפעמים תהיה הנקבה למעלה מזכר ויהיה הזכר טפל לה, ותזכר הנקבה מהטעם עצמו שיזכר הזכר תמיד ולא הנקבה, שהוא הטעם כי היא העיקר, ותמצא שאמרו בזוהר (פנחם רלא:) בסוד יותרת הכבד כי הנוקבא נותנת יותרת לזכר, וכבר כתבנו שכל מין הנאסר היא בחינת הקליפה המושלל מהחיים והטוב:
@51 **והוא גרה לא יגר**. פירש תנאי הוא הדבר לזמן שהוא לא יגר אבל לעתיד לבא יעלה גרה ויחזור להיות מותר, ולא שישאר בלא גרה ויותר כי תורה לא תשונה:
@54 **שקץ הם לכם**. פירוש ולצד זה שקץ יהיו לכם וטעם אומרו **ושקץ** בתוספות וא''ו, יתבאר על דרך אומרם בחולין (ה.) אין הקב''ה מביא תקלה וכו' וכל שכן על ידי צדיקים עצמן, וכתבו התוספת (שם) כי דוקא בענין איסור אכילה גנאי הוא לצדיקים שיבא לתוך גופן דבר איסור פירוש ואפילו בשוגג, וזה הוא שרמז כאן באומרו **ושקץ יהיו לכם** פירוש לרבות אפילו בשוגג שלא תתכוונו לאוכלם אף על פי כן ישקצו את הנפש. עוד ירמוז כי הם ישקצוהו ויסבבוהו להרים תולעים במותו, והוא אומרו **שקץ יהיו לכם** פירוש לעצמכם יעשו אתכם שקץ:
@58 **ואת האיה למינה**. (האיה) האמורה כאן כולל הרבה מינין שכולם מין איה, ותמצא שאמרו רז''ל (חולין סג:) כי ק''ך מיני עופות היו ידועים להם שכולם מין איה, ואפשר שיהיו עוד כהנה, וכן במינו של עורב ימצאו כמה וכמה הגם שאינם דומין ושמם משונה כסינונית לבנה (תו''כ וגמ' שם סב.) שהיא מין עורב:
@65 **אשר לו כרעים**. כבר הארכתי בחיבורי על טור ויורה דעה (סי' פה) שהעיקר כפירש''י בזה שצריך שיהיו לו כרעים הארוכים סמוכים לצוארו. והטועים להתירה כי אין מין זה בנמצא, אף אני השיבותי אותו גם אין מצויים אלא מין א' מהד' שהם שמנה אשר רשם ה' בטהרה (חולין סה.), גם אינם מצויים לפנינו מינים הטמאים שאין להם הכרעים בדרך זה, והם הרבים, למה שקדם לנו (שם סג) כי לא ימנה הכתוב אלא המועטים, וכאן מנה הטהורים אם כן הטמאים הם המרובין, ומעתה אין ראיה ממה שאין מצוי מין זה לומר שאיננו בעולם שהרי יש מינים הרבה ודאי ואינם מצויים כל עיקר אצלנו, לכן כל ירא וחרד ירא ויפחד לבל יושיט ידו לשקץ זה, וימחה בשולחי יד. והנה מיום שנשמעו דברי במערב ופירשו מהם הרבים לא נגע ה' עוד במכה זו ולא נראו זה יותר מי''ב שנה, כי תורה ומעשים טובים כתריס בפני הפורענות:
@67 **אשר לו ד' רגלים**. בתורת כהנים דרשו שבא להתיר מי שיש לו ה'. ונראה שהוא הדין מי שיש לו ו' וז' ולאו דוקא ה', וצריך לדעת לאיזה ענין התיר בת ה' מן הדיוק ולא אמר בפירוש כל שרץ העוף שיש לו ה' רגלים או על זה הדרך מד' רגלים ומעלה תאכלו. ואולי שהוצרך להשמיע גם כן דין היתר ציר חגבים טמאים, שדרשו ז''ל (בתו''כ) מאומרו בפסוק זה שקץ הוא פרט לעירוביו שהוא ציר כמאמרם שם, ולזה בחר להשמיענו היתר בת ה' רגלים באופן זה:
@68 **ולאלה תטמאו**. בתורת כהנים פירשו אומרו **ולאלה** על העתידים ליאמר בענין למטה. וקשה לי למה אמר ולאלה בתוס' וא''ו כיון שאין לו שייכות דין זה עם מה שלמעלה ממנו ולא שלמעלה עמו. ואולי נתכוון ליתן העליון כתחתון, פירוש שכל מין בהמה וחיה בין טמאים שאינם לא מעלה גרה ולא מפריסי פרסה שלא נרשמו כאן בכתוב, ובין טהורים שמעלים גרה ומפריסים פרסה ושוסעת שסע שלא נרשמו גם כן בכתוב ורמזם באומרו לכל הבהמה, וכלל זה חוזר למה שרשם בפרשת סימני בהמה, ולזה אמר ולאלה בוא''ו. כדי שלא תטעה ליתן כל האמור למעלה, לזה פרט שאין דבריו אלא בבהמה וחיה. או ירצה להסמיך דין טומאה לדין אכילה האמור בפרשה שלפניה וגו' מה אכילה בכזית גם טומאה בכזית. ובתורת כהנים העמידו הכתוב שלא בא אלא לטומאת אבר מן החי של בהמה טמאה ובהמה טהורה, ודרשו טומאה בכזית מפסוק אחר דכתיב (פסוק מ) והאוכל מנבלתה יכבם בגדיו וטמא עד הערב, וזה לשונם לא בא אלא ליתן שיעור לנוגע ולנושא בכזית כמו האוכל. ואפשר לומר עוד שרמז בסמיכות זה לומר שאם ילדה כמין בהמה הסמוך לה דינו שוה. וראיתי לראב''ע ז''ל שכתב שלדעתו נראה שמלת אלה חוזרת על כל הנזכרים למעלה, ודחה דעת האומר אלה לכל הבהמה וכו'. ואני אומר שיותר היה לו שלא לומר דבר שאינו נשמע ולא יחלוק על מקבלי תורה, כי מי ישמע לדבריו כאן ואפילו ללומדם והם הפך קבלת תורת משה, ומה גם בפשט הכתוב שאפילו בי רב זוטר כן יבין בתחילת ההשכל, וממי נעדר את אשר ראו עיניו ויותר מהמה, ומה כחו לחלוק עמהן גם בלא הכרח ואפילו אם יהיה המנגדו כיוצא בו ומכל שכן גדולים ממנו וכל שכן וקל וחומר אשר קטנם עבה ממתניו, וצא ולמד מה שאמרו האמוראים על גדולים שקדמום (שבת קיב:) אם הראשונים וכו'. וללמד על הרב ז''ל זכות אולי שפירוש זה לא כתבו אלא לסיבה ידועה לו, ונהג מנהג ע' זקנים (מגילה ט.) ששינו בכמה מקומות, וגם לזה ה' יכפר בעדו:
@73 **וזה לכם הטמא**. טעם אומרו וזה, לפי מה שפירשו שם בתורת כהנים בפרשה שלפניה שבא לטומאת אבר מן החי אמר וזה להשוות למה שלפניו שגם הוא מדבר בדין טומאת אבר מן החי שהאבר הוא שמטמא ולא הבשר הפורש בין בשרצים בין בבהמה וחיה. עוד נראה כי וא''ו האמורה כאן בתחילה לא להסמיך באה אלא לרמוז תוספת טומאה בשרץ שהוא טומאת דמו שיהיה מטמא כבשרו, מה שאין כן בבהמה טמאה כמאמר רז''ל בתורת כהנים (כאן) וכאילו אמר ועוד תוספת טומאה בזה. ואומרו **לכם** דרשו ז''ל (תו''כ כאן) שבא למעט שלא יכשיר הזרעים, דדוקא לטומאה ולא להכשירה, והוא אומרו לכם הוא טמא ולא מכשיר. עוד ירצה **לכם** הוא שהם טמאים אבל לא לגוים, שאין הגוים מקבלים טומאה כבהמות. ויש לחקור זאת איך לא מנה הכתוב הנחש שהוא אב הטומאה לכל טומאת השרצים ודומיהם ואולי שטומאת הנחש הוא בנפשו ולא בגופו ובמותו ישאר הגוף ריקם מכל כעפר הארץ כי אין טומאה דבקה בגופו לצד שאין בו ולא כלום וכיוצא בזה תמצא שאמרו ז''ל (ב''מ קיד:) גוים אין מטמאים באהל, וישראל מטמאים באהל והוא מהטעם עצמו, וטומאת השרצים בגופם יותר מבנפשם, ולזה יטמאו במותם ולא בחייהם, הא למדת כי הנחש טומאתו יותר מטומאת השרצים:
@73 **למינהו**. פשט למינהו יגיד כי יש הרבה מיני צב וכל שיש בו מינים הרבה או אפילו מין אחד לבד יאמר הכתוב למינהו. אלא שבהעור והרוטב (חולין קכב:) תניא וזה לשונם הטמאים לרבות עורותיהן כבשרן, יכול אפילו כולן תלמוד לומר אלה, והא אלה אכולהו כתיב, אמר רב למינהו הפסיק ע''כ. וקשה מנין לרב לומר כי למינהו באה להפסקה ולא לגופה לומר שיש בו מינים. ונראה כי רב אינו מכחיש משמעות הכתוב וכוונתו היא כי לצד שיש לפנינו רבוי של הטמאים לרבות עורותיהן, ואמר הכתוב סמוך לרבוי זה מיעוט דכתיב אלה, ואם לא היתה תיבת למינהו באיזה דרך נחלק אותן שבא עליהם הרבוי ואותן שמיעט, ומאומרו למינהו הגם שבאה לגופה תועיל גם כן להפריד בין המתרבים בטומאת עורותיהן, כיון שהכתוב גילה שיש חלוקה ביניהם לענין טומאה הרי זה מראה כי למינהו בא גם כן לסמן החלוקה. ובזה נתישבה קושית התוספת שם בד''ה למינהו וכו' תימא כיון דהפסיק בענין אלה למה לי עד כאן ולדרכנו לא קשה. גם לדברי תנא דמתניתין שם דמטמא עורותיהן משום דאזיל בתר גישתא אין להקשות עליו למינהו למה לי, שעכ''פ איצטריך למינהו לגופה כנזכר:
@75 **הטמאים**. לתנא שאינו דורש טומאת עורותיהן מהטמאים למה איצטריך, אז''ל (בתו''כ) שבא לרבות ביצת השרץ שרקמה. גם דרשו (ת''כ מעילה יז) שיצטרפו לטומאה דם בדם דם בבשר בין במין אחד בין בב' מינים. וצריך לדעת תיבת **אלה** מה בא למעט לדרכו. ונראה לפרשה על דרך מה שכתב הרמב''ם בפרק ד' מהלכות אבות הטומאות דם השרץ כבשרו ומצטרף לכעדשה כל זמן שהוא מחובר לבשרו, לזה אמר אלה למעט אם פירש הדם מן השרץ לא יצטרף עם הבשר:
@84 **והאוכל מנבלתה וגו'**. בתורת כהנים אמרו שלא בא הכתוב אלא ליתן שיעור לנוגע ולנושא שהוא כדי אכילת כזית, ואין כוונת הכתוב כפשוטו שתטמאנו בבית הבליעה, שהרי מצינו שאמר בנבלת עוף הטהור (אמור כב ח) ולא יאכל לטמאה בה, בה אתה מטמא בבית הבליעה ואי אתה מטמא בנבלת בהמה בבית הבליעה. וצריך לדעת למה לא אמרה התורה הדבר בפירוש, ואולי כי נתכוון הכתוב להרבה דינים שישנם בדין אכילה מלבד שיעור כזית, גם אמרו (חולין עא.) בשר השרץ שנפסד והבאיש ונפסל מלאכול הכלב טהור ע''כ, ודבר זה נלמד מדין אכילה כמו שכתבו התוספת עלה כ''ג דממה שאמר הכתוב (מלכים ב) בחלק יזרעאל יאכלו הכלבים אלמא אכילת כלבים שמה אכילה וכו', ואם כן לצד שנתכוין הכתוב להשוות הטומאה לדין אכילה בין לשיעור בין לשאר דברים לזה אם היה בא ללמד כל פרטי הדינים צריך להוסיף דברים רבים, וכסף נבחר לשון צדיק:
@84 . (מג) **אל תשקצו וגו'**. צריך לדעת למה חזר עוד לצוות לזה ורז''ל (בתו''כ) אמרו לרבות את שפירשו לארץ וחזרו, ודרשה זו אמת אלא שאינה צריכה כיון שפירשו וכי בשביל שחזרו יהיו מותרים. ויש ליישב דבריהם ז''ל. ואולי שבא הכתוב להודיע כי האוכל מהשרצים תעשה נפשו עצמה שרץ, והוא אומרו **אל תשקצו את נפשותיכם** פירוש לא תעשו נפשותיכם שקץ ובמה בכל השרץ השורץ על הארץ כשתאכלו אותה. ולך נא ראה מה שכתבנו בפרשת בראשית ברמז פסוק (א כו) וירדו בדגת הים וגו'. ותמצא מאמרם ז''ל (פסחים מט:) שאמרו על עמי הארץ הם שרץ ובנותיהם שקץ וגו', וכל דבריהם ז''ל ברוח הקודש נאמרו והם דברינו עצמם. ואומרו **ולא תטמאו בהם** אולי שיכוין לומר שצריכין ישראל להזהר לבל יכנסו לפיהם אפילו בהיסח הדעת, כי ההפרש שבין השוגג למזיד במציאות זה כשוגג כמזיד, כי התיעוב יעשה מעשהו בנפש אדם אפילו בהיסח הדעת, אלא שישתנה הפגם במעשה מזיד תעשה נפשו שקץ ובשוגג תטמא נפשו ותטמטם, והוא אומרו **ולא תטמאו ונטמתם בם**. וצריך האדם ליזהר בתוספת זהירות וזריזות בכל דבר אשר יכנס בגדר ספק שיקוץ זה, ומה גם בזמנים אלו שנזהם האויר והארצות כולן יחד ואין לך גידולי קרקע שאין בהם מהשיקוץ שומר נפשו ישמור את הדבר:
@88 **כי אני ה' אלהיכם**. פירוש ומשונה אומה ישראלית לקדושה וטהרה שלא בחר ה' ליקרא אלוה אלא לישראל, לזה צריך להרחיק מן הטומאה:
@88 **והתקדשתם וגו'**. פירוש אם אתם מתקדשים אני אקדש אתכם לבל יכנס לגופכם דבר שיקוץ על דרך אומרם (חולין ה:) אין הקדוש ב''ה מביא וכו' וכל שכן צדיקים עצמן, והעמידו התוספות מאמר זה בדבר איסור הנכנם לגופו של אדם כי הקב''ה ישמרהו בזה:
@88 **עוד** ירצה **והתקדשתם** תעשו גדרים וסייגים לבל תטמאו ובזה אני מבטיחכם שתהיו קדושים. וחזר ופירש באיזה דבר יהיו קדושים, ואמר **כי קדוש אני** הנה מה שתולה טעם קריאתם קדושים שהוא לצדו הא למדת כי השרה שכינתו על הפרושים ולזה יקראו על שמו. ואומרו **ולא תטמאו** וגו' פירוש מלבד דברים שאתה מעלה על דעתך לשמור עצמך מהם עוד אני מבטיחך שלא יאונה לך כל מין הרע, והוא אומרו בכל השרץ הרומש וגו'. עוד ירמוז שבאמצעות שמירת מצוה זו לא ישלטו עכו''ם בעם בני ישראל עכו''ם יקראו שרצים ושקצים הרומשים על הארץ:
@89 **כי אני ה' המעלה וגו'**. נותן הוכחה לעיניהם כי ה' ישמור אותם מהכשל בעון ההוא, כי הוא העלה וברר נפשות ישראל שהיו נתונים בקליפת מצרים כמו שפירשנו במקומו, ואם יזונו מהתיעוב הנה הנם חוזרים לשקע נפשם בקליפה כבראשונה, ואשר על כן כשיתקדשו הוא יגמור בעדם לשומרם. עוד ירצה לומר כי אין הקב''ה כביכול יכול ליחד שמו ולהשרות שכינתו אלא על המושלל ממין הרע ההוא, ולזה לא יחד שמו עליהם עד שהוציאם מארץ מצרים, ואם לא ישמרו עצמם מהתיעוב הנה הנם חוזרים להיות כמות שהיו קודם עלותם מארץ מצרים, ויהיו מושללים מבחינה זו:
@90 **זאת תורת הבהמה והעוף**. כל הכתוב מיותר ובתורת כהנים אמרו (בחולין כז:
@90 מבואר כדבדי רבינו) כי בא לומר משפט שחיטת העוף במה שסדר העוף בין הבהמה ובין הדגים שהם נפש החיה לומר חציו בהמה וחציו דג, לזה צריך סימן אחד בעוף או רובו. ולפי זה מצאנו טעם נכון שהוצרך הכתוב למעט הדגים מן השחיטה דכתיב (במדבר יא כב) יאסף, כי מנין יעלה על הדעת שצריכה, שהוצרך למעט, אלא לצד שהוצרך לכתוב דגי הים לתת בינו ובין הבהמה העוף, חש לטעות כי כוונת הכתוב הוא שהשוה הכתוב העופות והדגים לבהמה שכולן צריכין שחיטה ב' סימנים, לזה אמר בדגים אסיפה ובזה תבין כוונת ה' בפסוק שלא בא אלא לעוף להצריכו סימן אחד כנזכר. ואם תאמר אם כן למה הוצרך להזכיר כאן נפש השורצת שהם החגבים. ויש לומר שחש הכתוב לטעות מפסוק שמיעט שחיטה בדגים דכתיב יאסף וגו' כי לא מיעט אלא דגים ולא חגבים, לזה סדרם אחר הדגים לומר שאינם צריכין שחיטה כמשפט הדגים:
@90 **חסלת פרשת שמיני**
